#[derive(Debug, Clone, PartialEq, Eq)]
pub struct QueryResult {
    pub columns: Vec<String>,
    pub rows: Vec<Vec<Scalar>>,
}

struct ProjectionLabelOverride {
    index: usize,
    label: String,
}

pub fn execute(data_dir: &Path, sql: &str) -> Result<QueryResult, Error> {
    if let Some((expanded, label_override)) = expand_symbol_cursor(data_dir, sql)? {
        let mut result = execute(data_dir, &expanded)?;
        if let Some(label_override) = label_override {
            if let Some(column) = result.columns.get_mut(label_override.index) {
                *column = label_override.label;
            }
        }
        return Ok(result);
    }
    let query = parse_query(sql)?;
    if let Some(count) = query.long_sequence {
        let table = long_sequence_table(count)?;
        return execute_on(&table, &query);
    }
    if let Some(series) = &query.generate_series {
        let table = generate_series_table(series)?;
        return execute_on(&table, &query);
    }
    let table = open_table(data_dir, &query.table)?;
    if !query.join.is_empty() {
        let mut current = table;
        for join in &query.join {
            current = equi_join_table(&current, data_dir, join)?;
        }
        let mut result = execute_on(&current, &query)?;
        result.columns = disambiguate_join_names(result.columns);
        return Ok(result);
    }
    execute_on(&table, &query)
}

fn expand_symbol_cursor(
    data_dir: &Path,
    sql: &str,
) -> Result<Option<(String, Option<ProjectionLabelOverride>)>, Error> {
    let lower = sql.to_ascii_lowercase();
    let Some((in_marker, open, start)) = find_in_cursor_subquery(&lower) else {
        return Ok(None);
    };
    let Some(end) = matching_sql_paren(sql, open) else {
        return Ok(None);
    };
    let mut parseable = sql.to_string();
    while let Some((_, parse_open, _)) = find_in_cursor_subquery(&parseable.to_ascii_lowercase()) {
        let Some(parse_end) = matching_sql_paren(&parseable, parse_open) else {
            break;
        };
        parseable.replace_range(parse_open..=parse_end, "(NULL)");
    }
    let outer = parse_query(&parseable)?;
    let outer_table = query_source_table(data_dir, &outer)?;
    let mut lhs_prefix = sql[..in_marker].trim_end();
    if lhs_prefix.to_ascii_lowercase().ends_with(" not") {
        lhs_prefix = lhs_prefix[..lhs_prefix.len() - 3].trim_end();
    }
    let lhs = lhs_prefix
        .trim_end()
        .rsplit(|c: char| !(c.is_ascii_alphanumeric() || c == '_' || c == '.'))
        .next()
        .unwrap_or("");
    if lhs.is_empty() {
        if let Some((FilterOperand::Projection(expression), position)) =
            outer.filter.as_ref().and_then(filter_in_subquery_lhs)
        {
            if let ResolvedProj::MakeGeohash { bits, .. } = resolve_proj(&outer_table, expression)?
            {
                return Err(Error::at(
                    format!(
                        "there is no matching operator `in` with the argument types: {} in CURSOR",
                        geohash_type_name(bits)
                    ),
                    position,
                ));
            }
        }
        return Err(Error::at("constant expected", start));
    }
    let Some(lhs_index) = in_list_column_index(&outer_table, lhs).or_else(|| {
        lhs.rsplit('.')
            .next()
            .and_then(|bare| outer_table.column_index(bare))
    }) else {
        if lhs.is_empty() {
            return Err(Error::at("constant expected", start));
        }
        return Err(Error::at(
            format!("Invalid column: {lhs}"),
            lhs_prefix.rfind(lhs).unwrap_or(in_marker - lhs.len()),
        ));
    };
    let lhs_tag = outer_table.meta.columns[lhs_index].tag;
    if lhs_tag != qdb_types::TAG_SYMBOL {
        let message = match lhs_tag {
            qdb_types::TAG_BOOLEAN => {
                let member = cursor_first_column_tag(data_dir, &sql[start..end]).ok();
                let member_type = if member == Some(qdb_types::TAG_BOOLEAN) {
                    "BOOLEAN"
                } else {
                    "CURSOR"
                };
                format!("there is no matching operator `in` with the argument types: BOOLEAN in {member_type}")
            }
            qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR | qdb_types::TAG_CHAR => {
                "constant expected".to_string()
            }
            qdb_types::TAG_LONG
            | qdb_types::TAG_INT
            | qdb_types::TAG_SHORT
            | qdb_types::TAG_BYTE => "cannot compare LONG with type CURSOR".to_string(),
            qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => {
                "cannot compare DOUBLE with type CURSOR".to_string()
            }
            qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP => {
                "cannot compare TIMESTAMP with type CURSOR".to_string()
            }
            other => {
                return Err(Error::at(
                    format!(
                        "cannot compare {} with type CURSOR",
                        qdb_types::type_name(other)
                    ),
                    in_marker,
                ))
            }
        };
        let position = if lhs_tag == qdb_types::TAG_BOOLEAN {
            in_marker
        } else {
            start
        };
        return Err(Error::at(message, position));
    }

    let inner_sql = &sql[start..end];
    let tag = cursor_first_column_tag(data_dir, inner_sql)
        .map_err(|error| Error::at(error.message, start))?;
    if !matches!(
        tag,
        qdb_types::TAG_STRING | qdb_types::TAG_SYMBOL | qdb_types::TAG_VARCHAR
    ) {
        return Err(Error::at(
            format!(
                "supported column types are VARCHAR, SYMBOL and STRING, found: {}",
                qdb_types::type_name(tag)
            ),
            in_marker,
        ));
    }
    let values = execute(data_dir, inner_sql)?;
    let members = values
        .rows
        .iter()
        .map(|row| match row.first() {
            Some(Scalar::Text(value)) => Ok(format!("'{}'", value.replace('\'', "''"))),
            Some(Scalar::Null) | None => Ok("NULL".to_string()),
            _ => Err(Error::at("constant expected", start)),
        })
        .collect::<Result<Vec<_>, _>>()?;
    let negated = lower[..in_marker].trim_end().ends_with(" not");
    if members.is_empty() {
        let left_start = lhs_prefix.rfind(lhs).unwrap_or(in_marker - lhs.len());
        let mut expanded = sql.to_string();
        let select_projection =
            top_level_sql_keyword(&lower, b"from").is_some_and(|from| in_marker < from);
        let replacement = if select_projection {
            // SELECT projections do not accept a bare BOOLEAN literal, so use a
            // constant predicate with the same value when the cursor is empty.
            if negated {
                "starts_with('a', 'a')"
            } else {
                "starts_with('a', 'b')"
            }
        } else if negated {
            "true"
        } else {
            "false"
        };
        expanded.replace_range(left_start..=end, replacement);
        let label_override =
            projection_cursor_label_override(sql, &lower, in_marker, end, start, negated);
        return Ok(Some((expanded, label_override)));
    }
    let mut expanded = sql.to_string();
    expanded.replace_range(open..=end, &format!("({})", members.join(",")));
    let label_override =
        projection_cursor_label_override(sql, &lower, in_marker, end, start, negated);
    Ok(Some((expanded, label_override)))
}

fn top_level_sql_keyword(sql: &str, keyword: &[u8]) -> Option<usize> {
    let bytes = sql.as_bytes();
    let mut depth = 0usize;
    let mut quoted = false;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\'' {
            if quoted && bytes.get(i + 1) == Some(&b'\'') {
                i += 2;
                continue;
            }
            quoted = !quoted;
        } else if !quoted {
            match bytes[i] {
                b'(' => depth += 1,
                b')' => depth = depth.saturating_sub(1),
                _ => {}
            }
            if depth == 0
                && bytes[i..].starts_with(keyword)
                && (i == 0 || !(bytes[i - 1].is_ascii_alphanumeric() || bytes[i - 1] == b'_'))
                && bytes
                    .get(i + keyword.len())
                    .is_none_or(|b| !(b.is_ascii_alphanumeric() || *b == b'_'))
            {
                return Some(i);
            }
        }
        i += 1;
    }
    None
}

fn projection_cursor_label_override(
    sql: &str,
    lower: &str,
    in_marker: usize,
    end: usize,
    inner_start: usize,
    negated: bool,
) -> Option<ProjectionLabelOverride> {
    let select = top_level_sql_keyword(lower, b"select")?;
    let from = top_level_sql_keyword(lower, b"from")?;
    if in_marker >= from {
        return None;
    }
    let list_start = select + b"select".len();
    let ranges = top_level_ranges(sql, list_start, from, b',');
    let (index, (item_start, item_end)) = ranges
        .iter()
        .enumerate()
        .find(|(_, (start, end))| *start <= in_marker && in_marker < *end)?;
    let suffix = sql.get(end + 1..*item_end)?.trim();
    if !suffix.trim_start_matches(')').trim().is_empty() {
        return None;
    }
    let inner_sql = sql.get(inner_start..end)?;
    let inner_plan = render_simple_subquery_plan(inner_sql)?;
    let mut lhs = sql.get(*item_start..in_marker)?.trim_end();
    if negated {
        lhs = lhs.trim_end();
        lhs = lhs
            .strip_suffix("not")
            .or_else(|| lhs.strip_suffix("NOT"))?;
        lhs = lhs.trim_end();
    }
    let lhs = lhs.trim().trim_start_matches('(').trim();
    let expression = format!("{lhs} in ({inner_plan})");
    let label = if negated {
        format!("not({expression})")
    } else {
        expression
    };
    let inner_lower = inner_sql.to_ascii_lowercase();
    let max_label_len = if top_level_sql_keyword(&inner_lower, b"join").is_some() {
        60
    } else {
        64
    };
    let label = label.chars().take(max_label_len).collect::<String>();
    Some(ProjectionLabelOverride {
        index,
        label: label.trim_end().to_string(),
    })
}

fn render_simple_subquery_plan(sql: &str) -> Option<String> {
    let lower = sql.to_ascii_lowercase();
    let select = top_level_sql_keyword(&lower, b"select")?;
    let from = top_level_sql_keyword(&lower, b"from")?;
    if select != 0 || from <= select + 6 {
        return None;
    }
    let projection = sql.get(select + 6..from)?.trim();
    let projection_items = top_level_ranges(sql, select + 6, from, b',');
    let mut rendered_columns = Vec::with_capacity(projection_items.len());
    for (start, end) in projection_items {
        let item = sql.get(start..end)?.trim();
        if item.is_empty() {
            return None;
        }
        rendered_columns.push(render_query_model_select_item(item));
    }
    if projection.is_empty() {
        return None;
    }
    let from_start = from + 4;
    let where_pos = top_level_sql_keyword(&lower, b"where");
    let order_pos = top_level_sql_keyword(&lower, b"order");
    let limit_pos = top_level_sql_keyword(&lower, b"limit");
    let source_end = [where_pos, order_pos, limit_pos]
        .into_iter()
        .flatten()
        .filter(|position| *position > from_start)
        .min()
        .unwrap_or(sql.len());
    let source = normalize_query_model_tokens(sql.get(from_start..source_end)?.trim());
    if source.is_empty() {
        return None;
    }
    let mut input_model = source;
    if let Some(where_pos) = where_pos.filter(|position| *position > from_start) {
        let where_start = where_pos + 5;
        let where_end = [order_pos, limit_pos]
            .into_iter()
            .flatten()
            .filter(|position| *position > where_start)
            .min()
            .unwrap_or(sql.len());
        let predicate = normalize_query_model_tokens(sql.get(where_start..where_end)?.trim());
        if predicate.is_empty() {
            return None;
        }
        input_model.push_str(" where ");
        input_model.push_str(&predicate);
    }
    let mut model = format!(
        "select-choose {} from ({input_model})",
        rendered_columns.join(" ")
    );
    if let Some(limit_pos) = limit_pos.filter(|position| *position > from_start) {
        model.push_str(" limit ");
        model.push_str(&normalize_query_model_tokens(
            sql.get(limit_pos + 5..)?.trim(),
        ));
    }
    Some(model)
}

fn render_query_model_select_item(item: &str) -> String {
    let lower = item.to_ascii_lowercase();
    if let Some(as_pos) = lower.rfind(" as ") {
        return format!(
            "{} {}",
            normalize_query_model_tokens(item[..as_pos].trim()),
            normalize_query_model_tokens(item[as_pos + 4..].trim())
        );
    }
    let normalized = normalize_query_model_tokens(item);
    let is_simple_column = normalized
        .chars()
        .all(|character| character.is_ascii_alphanumeric() || matches!(character, '_' | '.'));
    if is_simple_column {
        if normalized.contains('.') {
            let output_name = normalized.rsplit('.').next().unwrap_or(&normalized);
            format!("{normalized} {output_name}")
        } else {
            normalized
        }
    } else {
        format!("{normalized} {normalized}")
    }
}

fn normalize_query_model_tokens(sql: &str) -> String {
    let characters: Vec<char> = sql.chars().collect();
    let mut output = String::with_capacity(sql.len());
    let mut i = 0;
    let mut quoted = false;
    while i < characters.len() {
        let character = characters[i];
        if character == '\'' {
            if quoted && characters.get(i + 1) == Some(&'\'') {
                output.push('\'');
                output.push('\'');
                i += 2;
                continue;
            }
            quoted = !quoted;
            output.push('\'');
            i += 1;
        } else if quoted {
            output.push(character);
            i += 1;
        } else if character.is_ascii_whitespace() {
            if !output.ends_with(' ') && !output.is_empty() {
                output.push(' ');
            }
            i += 1;
        } else if matches!(character, '=' | '<' | '>' | '!') {
            while output.ends_with(' ') {
                output.pop();
            }
            output.push(' ');
            output.push(character);
            i += 1;
            if characters
                .get(i)
                .is_some_and(|next| matches!(*next, '=' | '>'))
            {
                output.push(characters[i]);
                i += 1;
            }
            output.push(' ');
        } else if character == ',' {
            while output.ends_with(' ') {
                output.pop();
            }
            output.push_str(", ");
            i += 1;
        } else {
            output.push(character.to_ascii_lowercase());
            i += 1;
        }
    }
    output.trim().to_string()
}

fn top_level_ranges(sql: &str, start: usize, end: usize, delimiter: u8) -> Vec<(usize, usize)> {
    let bytes = sql.as_bytes();
    let mut ranges = Vec::new();
    let mut range_start = start;
    let mut depth = 0usize;
    let mut quoted = false;
    let mut i = start;
    while i < end {
        match bytes[i] {
            b'\'' => {
                if quoted && bytes.get(i + 1) == Some(&b'\'') {
                    i += 2;
                    continue;
                }
                quoted = !quoted;
            }
            b'(' if !quoted => depth += 1,
            b')' if !quoted => depth = depth.saturating_sub(1),
            byte if byte == delimiter && !quoted && depth == 0 => {
                ranges.push((range_start, i));
                range_start = i + 1;
            }
            _ => {}
        }
        i += 1;
    }
    ranges.push((range_start, end));
    ranges
}

fn filter_in_subquery_lhs(filter: &Filter) -> Option<(&FilterOperand, usize)> {
    match filter {
        Filter::InListExpression {
            value, position, ..
        } => Some((value, *position)),
        Filter::Not(inner) => filter_in_subquery_lhs(inner),
        Filter::And(left, right) | Filter::Or(left, right) => {
            filter_in_subquery_lhs(left).or_else(|| filter_in_subquery_lhs(right))
        }
        _ => None,
    }
}

fn cursor_first_column_tag(data_dir: &Path, sql: &str) -> Result<i32, Error> {
    let expanded = expand_symbol_cursor(data_dir, sql)?;
    let sql = expanded
        .as_ref()
        .map(|(expanded, _)| expanded.as_str())
        .unwrap_or(sql);
    let query = parse_query(sql)?;
    let table = query_source_table(data_dir, &query)?;
    match &query.columns {
        SelectList::Star => table
            .meta
            .columns
            .first()
            .map(|column| column.tag)
            .ok_or_else(|| Error::at("constant expected", 0)),
        SelectList::Columns(columns) => {
            let column = columns
                .first()
                .ok_or_else(|| Error::at("constant expected", 0))?;
            let index = table
                .column_index(&column.name)
                .ok_or_else(|| Error::new(format!("Invalid column: {}", column.name)))?;
            Ok(table.meta.columns[index].tag)
        }
        SelectList::Projection(projection) => {
            let item = projection
                .items
                .first()
                .ok_or_else(|| Error::at("constant expected", 0))?;
            if let Proj::Column(name) = item {
                let index = table
                    .column_index(name)
                    .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
                Ok(table.meta.columns[index].tag)
            } else {
                Ok(resolve_proj(&table, item)?.expr_tag())
            }
        }
        SelectList::Aggregate(aggregate) => {
            let input = aggregate_input(&table, aggregate)?;
            Ok(aggregate_order_tag(&input))
        }
        SelectList::Grouped(grouped) => match grouped.select_order.first() {
            Some(GroupedSelectItem::Key(index)) => select_operand_tag(
                &table,
                &grouped
                    .keys
                    .get(*index)
                    .ok_or_else(|| Error::at("constant expected", 0))?
                    .operand,
            ),
            Some(GroupedSelectItem::Aggregate(index)) => {
                let aggregate = grouped
                    .aggregates
                    .get(*index)
                    .ok_or_else(|| Error::at("constant expected", 0))?;
                let input = aggregate_input(&table, aggregate)?;
                Ok(aggregate_order_tag(&input))
            }
            None => Err(Error::at("constant expected", 0)),
        },
    }
}

fn query_source_table(data_dir: &Path, query: &Query) -> Result<Table, Error> {
    let mut table = open_table(data_dir, &query.table)?;
    for join in &query.join {
        table = equi_join_table(&table, data_dir, join)?;
    }
    Ok(table)
}

fn find_in_cursor_subquery(lower: &str) -> Option<(usize, usize, usize)> {
    let bytes = lower.as_bytes();
    let mut i = 0;
    let mut quoted = false;
    while i < bytes.len() {
        if bytes[i] == b'\'' {
            if quoted && bytes.get(i + 1) == Some(&b'\'') {
                i += 2;
                continue;
            }
            quoted = !quoted;
            i += 1;
            continue;
        }
        if !quoted
            && bytes[i..].starts_with(b"in")
            && (i == 0 || !(bytes[i - 1].is_ascii_alphanumeric() || bytes[i - 1] == b'_'))
        {
            let mut j = i + 2;
            while bytes.get(j).is_some_and(u8::is_ascii_whitespace) {
                j += 1;
            }
            if bytes.get(j) == Some(&b'(') {
                let open = j;
                j += 1;
                while bytes.get(j).is_some_and(u8::is_ascii_whitespace) {
                    j += 1;
                }
                if bytes[j..].starts_with(b"select")
                    && bytes
                        .get(j + 6)
                        .is_none_or(|b| !(b.is_ascii_alphanumeric() || *b == b'_'))
                {
                    return Some((i, open, j));
                }
            }
        }
        i += 1;
    }
    None
}

fn matching_sql_paren(sql: &str, open: usize) -> Option<usize> {
    let mut depth = 1usize;
    let mut quoted = false;
    for (i, byte) in sql.bytes().enumerate().skip(open + 1) {
        if byte == b'\'' {
            quoted = !quoted;
        } else if !quoted && byte == b'(' {
            depth += 1;
        } else if !quoted && byte == b')' {
            depth -= 1;
            if depth == 0 {
                return Some(i);
            }
        }
    }
    None
}

fn qualified_join_name(alias: &str, name: &str) -> String {
    if name.contains('.') {
        name.to_string()
    } else {
        format!("{alias}.{}", name.to_ascii_lowercase())
    }
}

fn join_column_index(table: &Table, name: &str) -> Result<usize, Error> {
    if let Some(index) = table.column_index(name) {
        return Ok(index);
    }
    let bare = name.rsplit('.').next().unwrap_or(name);
    if bare != name {
        if let Some(index) = table.column_index(bare) {
            return Ok(index);
        }
    }
    Err(Error::new(format!("Invalid column: {name}")))
}

fn cross_join_table(left: &Table, right: &Table, join: &EquiJoin) -> Result<Table, Error> {
    let width = left.columns.len() + right.columns.len();
    let mut columns = Vec::with_capacity(width);
    for _ in 0..width {
        columns.push(Vec::new());
    }
    for left_row in 0..left.row_count() {
        for right_row in 0..right.row_count() {
            for (column_index, column) in left.columns.iter().enumerate() {
                columns[column_index].push(column[left_row].clone());
            }
            for (column_index, column) in right.columns.iter().enumerate() {
                columns[left.columns.len() + column_index].push(column[right_row].clone());
            }
        }
    }
    let mut meta_columns = Vec::with_capacity(columns.len());
    for column in &left.meta.columns {
        meta_columns.push(ColumnMeta {
            name: qualified_join_name(&join.left_alias, &column.name),
            raw_type: column.raw_type,
            tag: column.tag,
            symbol_index: column.symbol_index,
        });
    }
    for column in &right.meta.columns {
        meta_columns.push(ColumnMeta {
            name: format!("{}.{}", join.right_alias, column.name.to_ascii_lowercase()),
            raw_type: column.raw_type,
            tag: column.tag,
            symbol_index: None,
        });
    }
    let rows = columns.first().map(Vec::len).unwrap_or(0);
    Ok(Table {
        name: left.name.clone(),
        meta: TableMeta {
            column_count: meta_columns.len(),
            partition_by: PARTITION_BY_NONE,
            timestamp_index: -1,
            version: qdb_types::METADATA_VERSION_10_1_0,
            table_id: left.meta.table_id,
            wal_enabled: false,
            columns: meta_columns,
        },
        txn: TxnHeader {
            txn: 0,
            transient_row_count: i64::try_from(rows).unwrap_or(i64::MAX),
            fixed_row_count: 0,
            min_timestamp: i64::MIN,
            max_timestamp: i64::MIN,
            symbol_counts: Vec::new(),
            partitions: Vec::new(),
        },
        columns,
        symbol_maps: left.symbol_maps.clone(),
    })
}

fn equi_join_table(left: &Table, data_dir: &Path, join: &EquiJoin) -> Result<Table, Error> {
    let right = open_table(data_dir, &join.right_table)?;
    if join.cross {
        return cross_join_table(left, &right, join);
    }
    let left_index = join_column_index(left, &join.left_column)?;
    let right_index = right
        .column_index(&join.right_column)
        .ok_or_else(|| Error::new(format!("Invalid column: {}", join.right_column)))?;
    let left_tag = left.meta.columns[left_index].tag;
    let right_tag = right.meta.columns[right_index].tag;
    let mut chains: Vec<(usize, Vec<usize>)> = Vec::new();
    for row in 0..right.row_count() {
        let key = &right.columns[right_index][row];
        let mut found = None;
        for (index, (head, _)) in chains.iter().enumerate() {
            if sql_cmp(
                &right.columns[right_index][*head],
                right_tag,
                CmpOp::Eq,
                key,
            )? {
                found = Some(index);
                break;
            }
        }
        if let Some(index) = found {
            chains[index].1.insert(0, row);
        } else {
            chains.push((row, vec![row]));
        }
    }
    let mut columns = Vec::with_capacity(left.columns.len() + right.columns.len());
    for _ in 0..left.columns.len() + right.columns.len() {
        columns.push(Vec::new());
    }
    let mut emitted = vec![false; right.row_count()];
    for left_row in 0..left.row_count() {
        let key = &left.columns[left_index][left_row];
        let mut matched = None;
        for (index, (head, _)) in chains.iter().enumerate() {
            if sql_cmp(key, left_tag, CmpOp::Eq, &right.columns[right_index][*head])? {
                matched = Some(index);
                break;
            }
        }
        let Some(index) = matched else {
            if join.left_outer {
                for (column_index, column) in left.columns.iter().enumerate() {
                    columns[column_index].push(column[left_row].clone());
                }
                for column_index in 0..right.columns.len() {
                    columns[left.columns.len() + column_index].push(Scalar::Null);
                }
            }
            continue;
        };
        for right_row in &chains[index].1 {
            emitted[*right_row] = true;
            for (column_index, column) in left.columns.iter().enumerate() {
                columns[column_index].push(column[left_row].clone());
            }
            for (column_index, column) in right.columns.iter().enumerate() {
                columns[left.columns.len() + column_index].push(column[*right_row].clone());
            }
        }
    }
    if join.right_outer {
        for right_row in 0..right.row_count() {
            if emitted[right_row] {
                continue;
            }
            for column_index in 0..left.columns.len() {
                columns[column_index].push(Scalar::Null);
            }
            for (column_index, column) in right.columns.iter().enumerate() {
                columns[left.columns.len() + column_index].push(column[right_row].clone());
            }
        }
    }
    let mut meta_columns = Vec::with_capacity(columns.len());
    for column in &left.meta.columns {
        meta_columns.push(ColumnMeta {
            name: qualified_join_name(&join.left_alias, &column.name),
            raw_type: column.raw_type,
            tag: column.tag,
            symbol_index: column.symbol_index,
        });
    }
    for column in &right.meta.columns {
        meta_columns.push(ColumnMeta {
            name: format!("{}.{}", join.right_alias, column.name.to_ascii_lowercase()),
            raw_type: column.raw_type,
            tag: column.tag,
            symbol_index: None,
        });
    }
    let rows = columns.first().map(Vec::len).unwrap_or(0);
    Ok(Table {
        name: left.name.clone(),
        meta: TableMeta {
            column_count: meta_columns.len(),
            partition_by: PARTITION_BY_NONE,
            timestamp_index: -1,
            version: qdb_types::METADATA_VERSION_10_1_0,
            table_id: left.meta.table_id,
            wal_enabled: false,
            columns: meta_columns,
        },
        txn: TxnHeader {
            txn: 0,
            transient_row_count: i64::try_from(rows).unwrap_or(i64::MAX),
            fixed_row_count: 0,
            min_timestamp: i64::MIN,
            max_timestamp: i64::MIN,
            symbol_counts: Vec::new(),
            partitions: Vec::new(),
        },
        columns,
        symbol_maps: left.symbol_maps.clone(),
    })
}

fn disambiguate_join_names(columns: Vec<String>) -> Vec<String> {
    let mut seen = std::collections::BTreeMap::<String, usize>::new();
    columns
        .into_iter()
        .map(|name| {
            let bare = name.rsplit('.').next().unwrap_or(&name).to_string();
            let count = seen.entry(bare.clone()).or_insert(0);
            *count += 1;
            if *count == 1 {
                bare
            } else {
                format!("{bare}_{count}")
            }
        })
        .collect()
}

fn generate_series_table(series: &GenerateSeries) -> Result<Table, Error> {
    let (tag, values) = match series {
        GenerateSeries::Long { start, end, step } => {
            (TAG_LONG, long_series_values(*start, *end, *step)?)
        }
        GenerateSeries::Double { start, end, step } => {
            (TAG_DOUBLE, double_series_values(*start, *end, *step)?)
        }
        GenerateSeries::Timestamp { start, end, step } => {
            let values = match step {
                SeriesStep::Fixed(step) => long_series_values(*start, *end, *step)?
                    .into_iter()
                    .map(|value| match value {
                        Scalar::Long(micros) => Scalar::Timestamp(micros),
                        other => other,
                    })
                    .collect(),
                SeriesStep::Months(stride) => calendar_series_values(*start, *end, *stride, true)?,
                SeriesStep::Years(stride) => calendar_series_values(*start, *end, *stride, false)?,
            };
            (TAG_TIMESTAMP, values)
        }
    };
    cursor_table("generate_series", "generate_series", tag, values)
}

fn long_series_values(mut start: i64, mut end: i64, step: i64) -> Result<Vec<Scalar>, Error> {
    if (start <= end && step < 0) || (start >= end && step > 0) {
        std::mem::swap(&mut start, &mut end);
    }
    let span = if end >= start {
        end.wrapping_sub(start)
    } else {
        start.wrapping_sub(end)
    };
    let steps = (span as u64) / step.unsigned_abs();
    let size = steps.saturating_add(1);
    let rows =
        usize::try_from(size).map_err(|_| Error::new("unsupported: generate_series count"))?;
    if rows > 1_000_000 {
        return Err(Error::new("unsupported: generate_series count"));
    }
    Ok((0..rows)
        .map(|index| {
            let offset = i64::try_from(index).unwrap_or(0);
            Scalar::Long(start.wrapping_add(step.wrapping_mul(offset)))
        })
        .collect())
}

fn calendar_series_values(
    mut start: i64,
    mut end: i64,
    stride: i32,
    months: bool,
) -> Result<Vec<Scalar>, Error> {
    if (start <= end && stride < 0) || (start >= end && stride > 0) {
        std::mem::swap(&mut start, &mut end);
    }
    let add = |value: i64, stride: i32| {
        if months {
            add_months(value, stride)
        } else {
            add_years(value, stride)
        }
    };
    let mut curr = add(start, -stride);
    let mut values = Vec::new();
    loop {
        let next = add(curr, stride);
        if !values.is_empty() && ((stride >= 0 && next <= curr) || (stride < 0 && next >= curr)) {
            break;
        }
        if (stride >= 0 && next > end) || (stride < 0 && next < end) {
            break;
        }
        if values.len() == 1_000_000 {
            return Err(Error::new("unsupported: generate_series count"));
        }
        values.push(Scalar::Timestamp(next));
        curr = next;
    }
    Ok(values)
}

fn add_months(micros: i64, months: i32) -> i64 {
    if months == 0 {
        return micros;
    }
    let day_micros = 86_400_000_000;
    let days = micros.div_euclid(day_micros);
    let time = micros.rem_euclid(day_micros);
    let (year, month, day) = qdb_types::civil_from_unix_days(days);
    let month = i32::try_from(month).unwrap_or(1);
    let day = i32::try_from(day).unwrap_or(1);
    let mut shifted = month - 1 + months;
    let (year, month) = if shifted >= 0 {
        (year + shifted / 12, shifted % 12 + 1)
    } else {
        let mut year = year + shifted / 12 - 1;
        shifted = -shifted % 12;
        if shifted == 0 {
            shifted = 12;
        }
        shifted = 12 - shifted + 1;
        if shifted == 1 {
            year += 1;
        }
        (year, shifted)
    };
    let max_day = days_in_month(year, u32::try_from(month).unwrap_or(1));
    let day = u32::try_from(day.min(max_day)).unwrap_or(1);
    let days = qdb_types::unix_days_from_civil(year, month as u32, day).unwrap_or(0);
    days * day_micros + time
}

fn add_years(micros: i64, years: i32) -> i64 {
    if years == 0 {
        return micros;
    }
    let day_micros = 86_400_000_000;
    let days = micros.div_euclid(day_micros);
    let time = micros.rem_euclid(day_micros);
    let (year, month, day) = qdb_types::civil_from_unix_days(days);
    let year = year + years;
    let max_day = days_in_month(year, month);
    let day = u32::try_from(i32::try_from(day).unwrap_or(1).min(max_day)).unwrap_or(1);
    let days = qdb_types::unix_days_from_civil(year, month, day).unwrap_or(0);
    days * day_micros + time
}

fn double_series_values(mut start: f64, mut end: f64, step: f64) -> Result<Vec<Scalar>, Error> {
    if (start <= end && step < 0.0) || (start >= end && step > 0.0) {
        std::mem::swap(&mut start, &mut end);
    }
    let mut values = Vec::new();
    let mut value = start;
    while values.len() <= 1_000_000 {
        if step >= 0.0 {
            if value > end {
                break;
            }
        } else if value < end {
            break;
        }
        if value.is_nan() {
            break;
        }
        values.push(Scalar::Double(value));
        value += step;
    }
    if values.len() > 1_000_000 {
        return Err(Error::new("unsupported: generate_series count"));
    }
    Ok(values)
}

fn cursor_table(name: &str, column: &str, tag: i32, values: Vec<Scalar>) -> Result<Table, Error> {
    let rows = values.len();
    Ok(Table {
        name: name.to_string(),
        meta: TableMeta {
            column_count: 1,
            partition_by: PARTITION_BY_NONE,
            timestamp_index: -1,
            version: qdb_types::METADATA_VERSION_10_1_0,
            table_id: 0,
            wal_enabled: false,
            columns: vec![ColumnMeta {
                name: column.to_string(),
                raw_type: tag,
                tag,
                symbol_index: None,
            }],
        },
        txn: TxnHeader {
            txn: 0,
            transient_row_count: i64::try_from(rows).unwrap_or(i64::MAX),
            fixed_row_count: 0,
            min_timestamp: i64::MIN,
            max_timestamp: i64::MIN,
            symbol_counts: Vec::new(),
            partitions: Vec::new(),
        },
        columns: vec![values],
        symbol_maps: Vec::new(),
    })
}

fn long_sequence_table(count: i64) -> Result<Table, Error> {
    let rows = usize::try_from(count.max(0))
        .map_err(|_| Error::new("unsupported: long_sequence count"))?;
    let values = (1..=rows)
        .map(|row| Scalar::Long(i64::try_from(row).unwrap_or(i64::MAX)))
        .collect();
    Ok(Table {
        name: "long_sequence".to_string(),
        meta: TableMeta {
            column_count: 1,
            partition_by: PARTITION_BY_NONE,
            timestamp_index: -1,
            version: qdb_types::METADATA_VERSION_10_1_0,
            table_id: 0,
            wal_enabled: false,
            columns: vec![ColumnMeta {
                name: "x".to_string(),
                raw_type: TAG_LONG,
                tag: TAG_LONG,
                symbol_index: None,
            }],
        },
        txn: TxnHeader {
            txn: 0,
            transient_row_count: i64::try_from(rows).unwrap_or(i64::MAX),
            fixed_row_count: 0,
            min_timestamp: i64::MIN,
            max_timestamp: i64::MIN,
            symbol_counts: Vec::new(),
            partitions: Vec::new(),
        },
        columns: vec![values],
        symbol_maps: Vec::new(),
    })
}

pub fn execute_on(table: &Table, query: &Query) -> Result<QueryResult, Error> {
    if !table.name.eq_ignore_ascii_case(&query.table) {
        return Err(Error::new(format!(
            "query table `{}` does not match opened table `{}`",
            query.table, table.name
        )));
    }
    if let Some(filter) = &query.filter {
        validate_filter_in_expression(table, filter)?;
        validate_filter_regex(table, filter)?;
    }
    if query.group_by.is_some()
        && !matches!(
            &query.columns,
            SelectList::Aggregate(_)
                | SelectList::Grouped(_)
                | SelectList::Columns(_)
                | SelectList::Projection(_)
        )
    {
        return Err(Error::new("unsupported: GROUP BY without an aggregate"));
    }
    let projection = match &query.columns {
        SelectList::Aggregate(aggregate) if query.group_by.is_none() => {
            return execute_aggregate(table, query, aggregate);
        }
        SelectList::Aggregate(aggregate) => {
            return execute_group(table, query, None, std::slice::from_ref(aggregate.as_ref()));
        }
        SelectList::Grouped(grouped) => {
            return execute_group(table, query, Some(grouped), &grouped.aggregates);
        }
        SelectList::Columns(columns) if query.group_by.is_some() => {
            return execute_group_keys(table, query, columns);
        }
        SelectList::Projection(items) if query.group_by.is_some() => {
            return execute_group_key_projection(table, query, items);
        }
        SelectList::Projection(items) => {
            return execute_projection(table, query, &items.items);
        }
        SelectList::Star => (0..table.meta.columns.len()).collect::<Vec<_>>(),
        SelectList::Columns(names) => {
            let mut indexes = Vec::with_capacity(names.len());
            for column in names {
                let index = table
                    .column_index(&column.name)
                    .ok_or_else(|| Error::new(format!("unknown column `{}`", column.name)))?;
                indexes.push(index);
            }
            indexes
        }
    };
    let mut row_ids = Vec::new();
    for row in 0..table.row_count() {
        if let Some(filter) = &query.filter {
            if !row_matches(table, row, filter)? {
                continue;
            }
        }
        row_ids.push(row);
    }
    if !query.order_by.is_empty() {
        let mut keys = Vec::with_capacity(query.order_by.len());
        for order in &query.order_by {
            let index = table
                .column_index(&order.column)
                .ok_or_else(|| Error::new(format!("unknown ORDER BY column `{}`", order.column)))?;
            keys.push((index, table.meta.columns[index].tag, order.descending));
        }
        row_ids.sort_by(|a, b| {
            for (index, tag, descending) in &keys {
                let mut ordering =
                    compare_asc(&table.columns[*index][*a], &table.columns[*index][*b], *tag);
                if *descending {
                    ordering = ordering.reverse();
                }
                if ordering != Ordering::Equal {
                    return ordering;
                }
            }
            Ordering::Equal
        });
    }
    if let Some(limit) = query.limit {
        if limit.lo < 0 && limit.hi > 0 && limit_follows_timestamp_order(table, query)? {
            return Err(Error::new("LIMIT <negative>, <positive> is not allowed"));
        }
        apply_limit(&mut row_ids, limit.lo, limit.hi);
    }
    let columns = projection
        .iter()
        .map(|index| table.meta.columns[*index].name.clone())
        .collect();
    let mut rows = Vec::with_capacity(row_ids.len());
    for row in row_ids {
        let values = projection
            .iter()
            .map(|index| table.columns[*index][row].clone())
            .collect();
        rows.push(values);
    }
    Ok(QueryResult { columns, rows })
}

fn execute_projection(table: &Table, query: &Query, items: &[Proj]) -> Result<QueryResult, Error> {
    let resolved = items
        .iter()
        .map(|item| {
            resolve_proj(table, item).map_err(|error| match item {
                Proj::Not(expression) => not_projection_error(expression, error),
                _ => error,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    validate_regexp_replace_arguments(&resolved)?;
    let mut row_ids = Vec::new();
    for row in 0..table.row_count() {
        if let Some(filter) = &query.filter {
            if !row_matches(table, row, filter)? {
                continue;
            }
        }
        row_ids.push(row);
    }
    for row in &row_ids {
        for item in &resolved {
            reject_negative_substring(table, *row, item)?;
        }
    }
    if !query.order_by.is_empty() {
        fill_timestamp_sequences(table, &resolved, &row_ids);
        let mut keys = Vec::with_capacity(query.order_by.len());
        for order in &query.order_by {
            if let Some(index) = resolved.iter().position(|item| {
                item.expr_label()
                    .is_some_and(|label| label.eq_ignore_ascii_case(&order.column))
            }) {
                keys.push(OrderKey::Expr(index, order.descending));
                continue;
            }
            let index = table
                .column_index(&order.column)
                .ok_or_else(|| Error::new(format!("unknown ORDER BY column `{}`", order.column)))?;
            keys.push(OrderKey::Column(
                index,
                table.meta.columns[index].tag,
                order.descending,
            ));
        }
        let mut order_error = None;
        row_ids.sort_by(|a, b| {
            if order_error.is_some() {
                return Ordering::Equal;
            }
            for key in &keys {
                let ordering = match key {
                    OrderKey::Column(index, tag, _) => Ok(compare_asc(
                        &table.columns[*index][*a],
                        &table.columns[*index][*b],
                        *tag,
                    )),
                    OrderKey::Expr(index, _) => eval_checked(table, *a, &resolved[*index])
                        .and_then(|left| {
                            eval_checked(table, *b, &resolved[*index]).map(|right| {
                                compare_asc(&left, &right, resolved[*index].expr_tag())
                            })
                        }),
                };
                let mut ordering = match ordering {
                    Ok(ordering) => ordering,
                    Err(err) => {
                        order_error = Some(err);
                        return Ordering::Equal;
                    }
                };
                if key.descending() {
                    ordering = ordering.reverse();
                }
                if ordering != Ordering::Equal {
                    return ordering;
                }
            }
            Ordering::Equal
        });
        if let Some(err) = order_error {
            return Err(err);
        }
    }
    if let Some(limit) = query.limit {
        if limit.lo < 0 && limit.hi > 0 && limit_follows_timestamp_order(table, query)? {
            return Err(Error::new("LIMIT <negative>, <positive> is not allowed"));
        }
        apply_limit(&mut row_ids, limit.lo, limit.hi);
    }
    if query.order_by.is_empty() {
        fill_timestamp_sequences(table, &resolved, &row_ids);
    }
    let columns = resolved
        .iter()
        .map(|item| match item {
            ResolvedProj::Column { index, .. } => table.meta.columns[*index].name.clone(),
            ResolvedProj::Concat { label, .. }
            | ResolvedProj::Length { label, .. }
            | ResolvedProj::Lower { label, .. }
            | ResolvedProj::LowerTrim { label, .. }
            | ResolvedProj::LowerNested { label, .. }
            | ResolvedProj::Upper { label, .. }
            | ResolvedProj::UpperTrim { label, .. }
            | ResolvedProj::UpperNested { label, .. }
            | ResolvedProj::Side { label, .. }
            | ResolvedProj::Substr { label, .. }
            | ResolvedProj::Trim { label, .. }
            | ResolvedProj::TrimNested { label, .. }
            | ResolvedProj::Replace { label, .. }
            | ResolvedProj::ReplaceNested { label, .. }
            | ResolvedProj::RegexpReplace { label, .. }
            | ResolvedProj::StartsWith { label, .. }
            | ResolvedProj::Glob { label, .. }
            | ResolvedProj::Ilike { label, .. }
            | ResolvedProj::Like { label, .. }
            | ResolvedProj::Switch { label, .. }
            | ResolvedProj::Bar { label, .. }
            | ResolvedProj::TimestampSequence { label, .. }
            | ResolvedProj::StrPos { label, .. }
            | ResolvedProj::SplitPart { label, .. }
            | ResolvedProj::Pad { label, .. }
            | ResolvedProj::QuoteIdent { label, .. }
            | ResolvedProj::SizePretty { label, .. }
            | ResolvedProj::Abs { label, .. }
            | ResolvedProj::Round { label, .. }
            | ResolvedProj::RoundDown { label, .. }
            | ResolvedProj::RoundUp { label, .. }
            | ResolvedProj::RoundHalfEven { label, .. }
            | ResolvedProj::Coalesce { label, .. }
            | ResolvedProj::NullIf { label, .. }
            | ResolvedProj::Cast { label, .. }
            | ResolvedProj::DateAdd { label, .. }
            | ResolvedProj::DateDiff { label, .. }
            | ResolvedProj::Year { label, .. }
            | ResolvedProj::Month { label, .. }
            | ResolvedProj::Day { label, .. }
            | ResolvedProj::Hour { label, .. }
            | ResolvedProj::Minute { label, .. }
            | ResolvedProj::Second { label, .. }
            | ResolvedProj::Millis { label, .. }
            | ResolvedProj::Micros { label, .. }
            | ResolvedProj::Nanos { label, .. }
            | ResolvedProj::ToUtc { label, .. }
            | ResolvedProj::ToTimezone { label, .. }
            | ResolvedProj::ToPgDate { label, .. }
            | ResolvedProj::DayOfWeek { label, .. }
            | ResolvedProj::WeekOfYear { label, .. }
            | ResolvedProj::DateTrunc { label, .. }
            | ResolvedProj::TimestampFloor { label, .. }
            | ResolvedProj::TimestampCeil { label, .. }
            | ResolvedProj::IsLeapYear { label, .. }
            | ResolvedProj::DaysInMonth { label, .. }
            | ResolvedProj::ToStr { label, .. }
            | ResolvedProj::IsEndOfMonth { label, .. }
            | ResolvedProj::DayOfWeekSundayFirst { label, .. }
            | ResolvedProj::ToTimestamp { label, .. }
            | ResolvedProj::ToDate { label, .. }
            | ResolvedProj::Md5 { label, .. }
            | ResolvedProj::Sha1 { label, .. }
            | ResolvedProj::Sha256 { label, .. }
            | ResolvedProj::Extract { label, .. }
            | ResolvedProj::Floor { label, .. }
            | ResolvedProj::Ceil { label, .. }
            | ResolvedProj::Sign { label, .. }
            | ResolvedProj::Sqrt { label, .. }
            | ResolvedProj::Sin { label, .. }
            | ResolvedProj::Cos { label, .. }
            | ResolvedProj::Tan { label, .. }
            | ResolvedProj::Asin { label, .. }
            | ResolvedProj::Acos { label, .. }
            | ResolvedProj::Atan { label, .. }
            | ResolvedProj::Atan2 { label, .. }
            | ResolvedProj::Degrees { label, .. }
            | ResolvedProj::Radians { label, .. }
            | ResolvedProj::Cot { label, .. }
            | ResolvedProj::Typeof { label, .. }
            | ResolvedProj::Not { label, .. }
            | ResolvedProj::Power { label, .. }
            | ResolvedProj::Mid { label, .. }
            | ResolvedProj::Spread { label, .. }
            | ResolvedProj::SpreadBps { label, .. }
            | ResolvedProj::Wmid { label, .. }
            | ResolvedProj::Between { label, .. }
            | ResolvedProj::InList { label, .. }
            | ResolvedProj::Eq { label, .. }
            | ResolvedProj::Add { label, .. }
            | ResolvedProj::Arithmetic { label, .. }
            | ResolvedProj::Neg { label, .. }
            | ResolvedProj::BitNot { label, .. }
            | ResolvedProj::And { label, .. }
            | ResolvedProj::Ln { label, .. }
            | ResolvedProj::Log { label, .. }
            | ResolvedProj::Exp { label, .. }
            | ResolvedProj::Pi { label, .. }
            | ResolvedProj::CurrentSchema { label, .. }
            | ResolvedProj::CurrentDatabase { label, .. }
            | ResolvedProj::CurrentUser { label, .. }
            | ResolvedProj::SessionUser { label, .. }
            | ResolvedProj::CurrentCatalog { label, .. }
            | ResolvedProj::Version { label, .. }
            | ResolvedProj::PgIsInRecovery { label, .. }
            | ResolvedProj::FormatType { label, .. }
            | ResolvedProj::CurrentSetting { label, .. }
            | ResolvedProj::PgGetPartKeyDef { label, .. }
            | ResolvedProj::PgGetUserById { label, .. }
            | ResolvedProj::PgTableIsVisible { label, .. }
            | ResolvedProj::PgAge { label, .. }
            | ResolvedProj::PgGetExpr { label, .. }
            | ResolvedProj::Netmask { label, .. }
            | ResolvedProj::GeoDistance { label, .. }
            | ResolvedProj::GeoWithin { label, .. }
            | ResolvedProj::WithinRadius { label, .. }
            | ResolvedProj::WithinBox { label, .. }
            | ResolvedProj::MakeGeohash { label, .. }
            | ResolvedProj::ToUuid { label, .. }
            | ResolvedProj::JsonExtract { label, .. }
            | ResolvedProj::ToChar { label, .. }
            | ResolvedProj::Greatest { label, .. }
            | ResolvedProj::Least { label, .. } => label.clone(),
        })
        .collect();
    let mut rows = Vec::with_capacity(row_ids.len());
    for row in row_ids {
        let mut values = Vec::with_capacity(resolved.len());
        for (expression, item) in items.iter().zip(&resolved) {
            let value = eval_checked(table, row, item).map_err(|error| match expression {
                Proj::Not(expression) => not_projection_error(expression, error),
                _ => error,
            })?;
            values.push(value);
        }
        rows.push(values);
    }
    Ok(QueryResult { columns, rows })
}

enum OrderKey {
    Column(usize, i32, bool),
    Expr(usize, bool),
}

impl OrderKey {
    fn descending(&self) -> bool {
        match self {
            Self::Column(_, _, descending) | Self::Expr(_, descending) => *descending,
        }
    }
}

