fn ln_input(table: &Table, arg: &ConcatArg) -> Result<SqrtInput, Error> {
    match power_input(table, arg) {
        Ok(input) => Ok(input),
        Err(err) if err.message.starts_with("expression type mismatch") => {
            Err(match concat_arg_type(table, arg) {
                Ok(actual) => Error::new(format!(
                "argument type mismatch for function `ln` at #1 expected: DOUBLE, actual: {actual}"
            )),
                Err(column) => column,
            })
        }
        Err(err) => Err(err),
    }
}

fn resolve_power(table: &Table, expr: &PowerExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `power`; expected: 2, provided: {}",
            expr.args.len()
        )));
    }
    let base = power_input(table, &expr.args[0])?;
    let exponent = power_input(table, &expr.args[1])?;
    Ok(ResolvedProj::Power {
        label: expr.label.clone(),
        base,
        exponent,
    })
}

fn resolve_mid(table: &Table, expr: &MidExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `mid`; expected: 2, provided: {}",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::Mid {
        label: expr.label.clone(),
        bid: power_input(table, &expr.args[0])?,
        ask: power_input(table, &expr.args[1])?,
    })
}

fn mid_value(table: &Table, row: usize, bid: &SqrtInput, ask: &SqrtInput) -> Scalar {
    let (Some(bid), Some(ask)) = (sqrt_number(table, row, bid), sqrt_number(table, row, ask))
    else {
        return Scalar::Null;
    };
    if bid.is_nan() || ask.is_nan() {
        return Scalar::Null;
    }
    Scalar::Double((ask + bid) / 2.0)
}

fn resolve_spread(table: &Table, expr: &SpreadExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `spread`; expected: 2, provided: {}",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::Spread {
        label: expr.label.clone(),
        bid: power_input(table, &expr.args[0])?,
        ask: power_input(table, &expr.args[1])?,
    })
}

fn spread_value(table: &Table, row: usize, bid: &SqrtInput, ask: &SqrtInput) -> Scalar {
    let (Some(bid), Some(ask)) = (sqrt_number(table, row, bid), sqrt_number(table, row, ask))
    else {
        return Scalar::Null;
    };
    if bid.is_nan() || ask.is_nan() {
        return Scalar::Null;
    }
    Scalar::Double(ask - bid)
}

enum BetweenInput {
    Null,
    Constant(i64),
    Column { index: usize },
}

fn resolve_between(table: &Table, expr: &BetweenExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() < 3 {
        return Err(Error::new(format!(
            "too few arguments for 'between' [found={},expected=3]",
            expr.args.len()
        )));
    }
    if expr.args.len() > 3 {
        return Err(Error::new(format!(
            "too many arguments for 'between' [found={},expected=3]",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::Between {
        label: expr.label.clone(),
        value: between_input(table, &expr.args[0])?,
        low: between_input(table, &expr.args[1])?,
        high: between_input(table, &expr.args[2])?,
        negated: expr.negated,
    })
}

fn between_input(table: &Table, arg: &ConcatArg) -> Result<BetweenInput, Error> {
    match arg {
        ConcatArg::Column(name) => {
            let Some(index) = table.column_index(name) else {
                return Err(Error::new(format!("Invalid column: {name}")));
            };
            match table.meta.columns[index].tag {
                qdb_types::TAG_TIMESTAMP
                | qdb_types::TAG_DATE
                | qdb_types::TAG_LONG
                | qdb_types::TAG_INT
                | qdb_types::TAG_SHORT
                | qdb_types::TAG_BYTE => Ok(BetweenInput::Column { index }),
                tag => Err(between_type_rejected(qdb_types::type_name(tag))),
            }
        }
        ConcatArg::Literal(Scalar::Null) => Ok(BetweenInput::Null),
        ConcatArg::Literal(Scalar::Long(number)) => Ok(BetweenInput::Constant(*number)),
        other => Err(between_type_rejected(between_literal_type(other))),
    }
}

fn between_literal_type(arg: &ConcatArg) -> &'static str {
    match arg {
        ConcatArg::Literal(Scalar::Double(_)) => "DOUBLE",
        ConcatArg::Literal(Scalar::Float(_)) => "FLOAT",
        ConcatArg::Literal(Scalar::Boolean(_)) => "BOOLEAN",
        ConcatArg::Literal(Scalar::Char(_)) => "CHAR",
        ConcatArg::Literal(Scalar::Text(text)) if text.chars().count() == 1 => "CHAR",
        ConcatArg::Literal(Scalar::Text(_)) => "STRING",
        ConcatArg::Literal(Scalar::Timestamp(_)) => "TIMESTAMP",
        ConcatArg::Literal(Scalar::Date(_)) => "DATE",
        ConcatArg::Literal(Scalar::Long(number)) if i32::try_from(*number).is_ok() => "INT",
        ConcatArg::Literal(Scalar::Long(_)) => "LONG",
        ConcatArg::Literal(Scalar::Null) => "NULL",
        _ => "UNSUPPORTED",
    }
}

fn between_type_rejected(actual: &str) -> Error {
    Error::new(format!(
        "there is no matching operator `between` with the argument type: {actual}"
    ))
}

fn between_long(table: &Table, row: usize, input: &BetweenInput) -> Option<i64> {
    match input {
        BetweenInput::Null => None,
        BetweenInput::Constant(number) if *number == i64::MIN => None,
        BetweenInput::Constant(number) => Some(*number),
        BetweenInput::Column { index } => match table.columns[*index][row] {
            Scalar::Null => None,
            Scalar::Long(number) | Scalar::Timestamp(number) | Scalar::Date(number) => Some(number),
            Scalar::Int(number) => Some(i64::from(number)),
            Scalar::Short(number) => Some(i64::from(number)),
            Scalar::Byte(number) => Some(i64::from(number)),
            _ => None,
        },
    }
}

fn between_value(
    table: &Table,
    row: usize,
    value: &BetweenInput,
    low: &BetweenInput,
    high: &BetweenInput,
) -> Scalar {
    let (Some(value), Some(low), Some(high)) = (
        between_long(table, row, value),
        between_long(table, row, low),
        between_long(table, row, high),
    ) else {
        return Scalar::Boolean(false);
    };
    let (low, high) = if low <= high {
        (low, high)
    } else {
        (high, low)
    };
    Scalar::Boolean(low <= value && value <= high)
}

#[derive(Clone, Copy)]
enum InKind {
    Integer,
    Float,
    Date,
    Timestamp,
    Uuid,
    Ipv4,
    Text,
}

enum InItem {
    Null,
    Long(i64),
    Double(f64),
    Text(String),
    Uuid(String),
    Ipv4(String),
}

fn resolve_add(table: &Table, expr: &AddExpr) -> Result<ResolvedProj, Error> {
    let Some(index) = table.column_index(&expr.value) else {
        return Err(Error::new(format!("Invalid column: {}", expr.value)));
    };
    let tag = table.meta.columns[index].tag;
    let spelling = expr.op.spelling();
    let (result_tag, other) = if let Some(name) = &expr.other {
        let Some(other) = table.column_index(name) else {
            return Err(Error::new(format!("Invalid column: {name}")));
        };
        let other_tag = table.meta.columns[other].tag;
        let result_tag = match (tag, other_tag) {
            (qdb_types::TAG_LONG, qdb_types::TAG_LONG)
            | (qdb_types::TAG_LONG, qdb_types::TAG_INT)
            | (qdb_types::TAG_INT, qdb_types::TAG_LONG) => qdb_types::TAG_LONG,
            (qdb_types::TAG_INT, qdb_types::TAG_INT) => qdb_types::TAG_INT,
            (qdb_types::TAG_DOUBLE, qdb_types::TAG_DOUBLE) => qdb_types::TAG_DOUBLE,
            _ => {
                return Err(Error::new(format!(
                    "there is no matching operator `{spelling}` with the argument type: {}",
                    qdb_types::type_name(tag)
                )))
            }
        };
        (result_tag, Some(other))
    } else {
        let result_tag = match tag {
            qdb_types::TAG_LONG | qdb_types::TAG_INT | qdb_types::TAG_DOUBLE => tag,
            other => {
                return Err(Error::new(format!(
                    "there is no matching operator `{spelling}` with the argument type: {}",
                    qdb_types::type_name(other)
                )))
            }
        };
        (result_tag, None)
    };
    if expr.other.is_none()
        && matches!(expr.literal, Scalar::Double(_))
        && tag != qdb_types::TAG_DOUBLE
    {
        return Err(Error::new(format!(
            "there is no matching operator `{spelling}` with the argument type: {}",
            qdb_types::type_name(tag)
        )));
    }
    if expr.other.is_none()
        && !matches!(
            expr.literal,
            Scalar::Null | Scalar::Long(_) | Scalar::Double(_)
        )
    {
        return Err(Error::new(format!(
            "there is no matching operator `{spelling}` with the argument type: STRING"
        )));
    }
    Ok(ResolvedProj::Add {
        label: expr.label.clone(),
        index,
        result_tag,
        literal: expr.literal.clone(),
        other,
        op: expr.op,
    })
}

fn resolve_arithmetic(table: &Table, expr: &ArithmeticExpr) -> Result<ResolvedProj, Error> {
    let result_tag = select_operand_tag(table, &expr.operand).map_err(|error| {
        if let Some(name) = error
            .message
            .strip_prefix("unknown column `")
            .and_then(|message| message.strip_suffix('`'))
        {
            let position = expr
                .source
                .find(name)
                .map_or(expr.position, |offset| expr.position + offset);
            Error::at(format!("Invalid column: {name}"), position)
        } else {
            error
        }
    })?;
    Ok(ResolvedProj::Arithmetic {
        label: expr.label.clone(),
        operand: expr.operand.clone(),
        result_tag,
    })
}

fn select_operand_tag(table: &Table, operand: &FilterOperand) -> Result<i32, Error> {
    let FilterOperand::Arithmetic(expr) = operand else {
        return filter_operand_tag(table, operand);
    };
    let left_tag = select_operand_tag(table, &expr.left)?;
    let right_tag = select_operand_tag(table, &expr.right)?;
    if !is_numeric_tag(left_tag) || !is_numeric_tag(right_tag) {
        return filter_operand_tag(table, operand);
    }
    if matches!(left_tag, qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP)
        && expr.op == ArithOp::Sub
        && matches!(
            &expr.right,
            FilterOperand::Literal(value)
                if literal_tag(value) == qdb_types::TAG_INT
        )
    {
        return Ok(qdb_types::TAG_TIMESTAMP);
    }
    Ok(arithmetic_result_tag(left_tag, right_tag, expr.op))
}

fn eval_select_operand(
    table: &Table,
    row: usize,
    operand: &FilterOperand,
) -> Result<(Scalar, i32), Error> {
    let FilterOperand::Arithmetic(expr) = operand else {
        return eval_filter_operand(table, row, operand);
    };
    let (left, left_tag) = eval_select_operand(table, row, &expr.left)?;
    let (right, right_tag) = eval_select_operand(table, row, &expr.right)?;
    let subtract_integer_literal = expr.op == ArithOp::Sub
        && matches!(left_tag, qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP)
        && matches!(
            &expr.right,
            FilterOperand::Literal(value)
                if literal_tag(value) == qdb_types::TAG_INT
        );
    select_arithmetic_value(
        &left,
        left_tag,
        &right,
        right_tag,
        expr.op,
        expr.position,
        subtract_integer_literal,
    )
    .map_err(|error| {
        if error.position.is_none() && error.message.starts_with("inconvertible value:") {
            Error::at(error.message, 0)
        } else {
            error
        }
    })
}

fn select_arithmetic_value(
    left: &Scalar,
    left_tag: i32,
    right: &Scalar,
    right_tag: i32,
    op: ArithOp,
    position: usize,
    subtract_integer_literal: bool,
) -> Result<(Scalar, i32), Error> {
    if left.is_null() || right.is_null() {
        let tag = if subtract_integer_literal {
            qdb_types::TAG_TIMESTAMP
        } else {
            arithmetic_result_tag(left_tag, right_tag, op)
        };
        return Ok((Scalar::Null, tag));
    }
    if subtract_integer_literal {
        let left = temporal_as_micros(left, left_tag)?;
        let right = scalar_as_i64(right)?;
        let value = apply_i64(op, left, right).map_or(Scalar::Null, |value| {
            integer_arithmetic_result(value, qdb_types::TAG_TIMESTAMP)
        });
        return Ok((value, qdb_types::TAG_TIMESTAMP));
    }
    filter_arithmetic_value(left, left_tag, right, right_tag, op, position)
}

enum ResolvedAnd {
    Literal(Scalar),
    Column(usize),
}

fn resolve_and(table: &Table, expr: &AndExpr) -> Result<ResolvedProj, Error> {
    let Some(left) = table.column_index(&expr.left) else {
        return Err(Error::new(format!("Invalid column: {}", expr.left)));
    };
    if table.meta.columns[left].tag != qdb_types::TAG_BOOLEAN {
        return Err(Error::new(format!(
            "expression type mismatch, expected: BOOLEAN, actual: {}",
            qdb_types::type_name(table.meta.columns[left].tag)
        )));
    }
    let right = match &expr.right {
        AndRight::Literal(value @ (Scalar::Null | Scalar::Boolean(_))) => {
            ResolvedAnd::Literal(value.clone())
        }
        AndRight::Literal(_) => {
            return Err(Error::new(
                "expression type mismatch, expected: BOOLEAN, actual: STRING",
            ));
        }
        AndRight::Column(name) => {
            let Some(index) = table.column_index(name) else {
                return Err(Error::new(format!("Invalid column: {name}")));
            };
            if table.meta.columns[index].tag != qdb_types::TAG_BOOLEAN {
                return Err(Error::new(format!(
                    "expression type mismatch, expected: BOOLEAN, actual: {}",
                    qdb_types::type_name(table.meta.columns[index].tag)
                )));
            }
            ResolvedAnd::Column(index)
        }
    };
    Ok(ResolvedProj::And {
        label: expr.label.clone(),
        left,
        right,
        op: expr.op,
    })
}

fn and_value(table: &Table, row: usize, left: usize, right: &ResolvedAnd, op: BoolOp) -> Scalar {
    let left_true = matches!(table.columns[left][row], Scalar::Boolean(true));
    let right_true = match right {
        ResolvedAnd::Literal(value) => matches!(value, Scalar::Boolean(true)),
        ResolvedAnd::Column(index) => matches!(table.columns[*index][row], Scalar::Boolean(true)),
    };
    let result = match op {
        BoolOp::And => left_true && right_true,
        BoolOp::Or => left_true || right_true,
    };
    Scalar::Boolean(result)
}

fn resolve_bit_not(table: &Table, expr: &BitNotExpr) -> Result<ResolvedProj, Error> {
    let Some(index) = table.column_index(&expr.value) else {
        return Err(Error::new(format!("Invalid column: {}", expr.value)));
    };
    let tag = table.meta.columns[index].tag;
    let result_tag = match tag {
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_SYMBOL
        | qdb_types::TAG_CHAR => qdb_types::TAG_INT,
        qdb_types::TAG_LONG
        | qdb_types::TAG_DATE
        | qdb_types::TAG_TIMESTAMP
        | qdb_types::TAG_STRING
        | qdb_types::TAG_VARCHAR => qdb_types::TAG_LONG,
        other => {
            return Err(Error::new(format!(
                "there is no matching operator `~` with the argument type: {}",
                qdb_types::type_name(other)
            )))
        }
    };
    Ok(ResolvedProj::BitNot {
        label: expr.label.clone(),
        index,
        result_tag,
    })
}

fn bit_not_value(table: &Table, row: usize, index: usize) -> Result<Scalar, Error> {
    let tag = table.meta.columns[index].tag;
    match &table.columns[index][row] {
        Scalar::Null => Ok(Scalar::Null),
        Scalar::Byte(number) => Ok(Scalar::Int(!i32::from(*number))),
        Scalar::Short(number) => Ok(Scalar::Int(!i32::from(*number))),
        Scalar::Int(number) => Ok(Scalar::Int(!number)),
        Scalar::Long(number) => Ok(Scalar::Long(!number)),
        Scalar::Date(number) | Scalar::Timestamp(number) => Ok(Scalar::Long(!number)),
        Scalar::Char(unit) => {
            let ch = char::from_u32(u32::from(*unit)).unwrap_or('\u{0}');
            match parse_questdb_long(&ch.to_string()).and_then(|value| i32::try_from(value).ok()) {
                Some(number) => Ok(Scalar::Int(!number)),
                None => Err(Error::new(format!(
                    "inconvertible value: {ch} [CHAR -> INT]"
                ))),
            }
        }
        Scalar::Text(text) if tag == qdb_types::TAG_SYMBOL => {
            let map_index = table.meta.columns[index]
                .symbol_index
                .ok_or_else(|| Error::new("internal: symbol column"))?;
            let key = table.symbol_maps[map_index]
                .iter()
                .position(|found| found == text)
                .ok_or_else(|| Error::new("internal: symbol key"))?;
            let key = i32::try_from(key).map_err(|_| Error::new("internal: symbol key"))?;
            Ok(Scalar::Int(!key))
        }
        Scalar::Text(text) => {
            let kind = if tag == qdb_types::TAG_VARCHAR {
                "VARCHAR"
            } else {
                "STRING"
            };
            match parse_questdb_long(text) {
                Some(number) => Ok(Scalar::Long(!number)),
                None => Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> LONG]"
                ))),
            }
        }
        _ => Err(Error::new("internal: bitwise not")),
    }
}

fn resolve_neg(table: &Table, expr: &NegExpr) -> Result<ResolvedProj, Error> {
    let Some(index) = table.column_index(&expr.value) else {
        return Err(Error::new(format!("Invalid column: {}", expr.value)));
    };
    let tag = table.meta.columns[index].tag;
    let result_tag = match tag {
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_LONG
        | qdb_types::TAG_FLOAT
        | qdb_types::TAG_DOUBLE => tag,
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => qdb_types::TAG_DOUBLE,
        other => {
            return Err(Error::new(format!(
                "there is no matching operator `-` with the argument type: {}",
                qdb_types::type_name(other)
            )))
        }
    };
    Ok(ResolvedProj::Neg {
        label: expr.label.clone(),
        index,
        result_tag,
    })
}

fn neg_value(table: &Table, row: usize, index: usize) -> Result<Scalar, Error> {
    let tag = table.meta.columns[index].tag;
    match &table.columns[index][row] {
        Scalar::Null => Ok(Scalar::Null),
        Scalar::Byte(number) => Ok(Scalar::Byte(number.wrapping_neg())),
        Scalar::Short(number) => Ok(Scalar::Short(number.wrapping_neg())),
        Scalar::Int(number) => Ok(Scalar::Int(number.wrapping_neg())),
        Scalar::Long(number) => Ok(Scalar::Long(number.wrapping_neg())),
        Scalar::Float(number) => Ok(Scalar::Float(-number)),
        Scalar::Double(number) => Ok(Scalar::Double(-number)),
        Scalar::Text(text) => {
            let kind = if tag == qdb_types::TAG_VARCHAR {
                "VARCHAR"
            } else {
                "STRING"
            };
            match parse_questdb_f64(text) {
                Some(number) => Ok(Scalar::Double(-number)),
                None => Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                ))),
            }
        }
        _ => Err(Error::new("internal: unary minus")),
    }
}

fn apply_i64(op: ArithOp, left: i64, right: i64) -> Option<i64> {
    if matches!(op, ArithOp::Div | ArithOp::Mod) && right == 0 {
        return None;
    }
    Some(match op {
        ArithOp::Add => left.wrapping_add(right),
        ArithOp::Sub => left.wrapping_sub(right),
        ArithOp::Mul => left.wrapping_mul(right),
        ArithOp::Div => left.wrapping_div(right),
        ArithOp::Mod => left.wrapping_rem(right),
        ArithOp::BitAnd => left & right,
        ArithOp::BitOr => left | right,
        ArithOp::BitXor => left ^ right,
    })
}

fn apply_f64(op: ArithOp, left: f64, right: f64) -> Option<f64> {
    if matches!(op, ArithOp::Div | ArithOp::Mod) && right == 0.0 {
        return None;
    }
    let value = match op {
        ArithOp::Add => left + right,
        ArithOp::Sub => left - right,
        ArithOp::Mul => left * right,
        ArithOp::Div => left / right,
        ArithOp::Mod => left % right,
        ArithOp::BitAnd | ArithOp::BitOr | ArithOp::BitXor => return None,
    };
    if matches!(op, ArithOp::Div | ArithOp::Mod) && !value.is_finite() {
        None
    } else {
        Some(value)
    }
}

fn apply_f32(op: ArithOp, left: f32, right: f32) -> Option<f32> {
    if matches!(op, ArithOp::Div | ArithOp::Mod) && right == 0.0 {
        return None;
    }
    Some(match op {
        ArithOp::Add => left + right,
        ArithOp::Sub => left - right,
        ArithOp::Mul => left * right,
        ArithOp::Div => left / right,
        ArithOp::Mod => left % right,
        ArithOp::BitAnd | ArithOp::BitOr | ArithOp::BitXor => return None,
    })
}

fn add_column_i64(value: &Scalar) -> Option<i64> {
    match value {
        Scalar::Long(number) => Some(*number),
        Scalar::Int(number) => Some(i64::from(*number)),
        _ => None,
    }
}

fn add_value(
    table: &Table,
    row: usize,
    index: usize,
    result_tag: i32,
    literal: &Scalar,
    other: Option<usize>,
    op: ArithOp,
) -> Scalar {
    if let Some(other) = other {
        let left = &table.columns[index][row];
        let right = &table.columns[other][row];
        if left.is_null() || right.is_null() {
            return Scalar::Null;
        }
        return match result_tag {
            qdb_types::TAG_LONG => match (add_column_i64(left), add_column_i64(right)) {
                (Some(left), Some(right)) => {
                    apply_i64(op, left, right).map_or(Scalar::Null, Scalar::Long)
                }
                _ => Scalar::Null,
            },
            qdb_types::TAG_INT => match (left, right) {
                (Scalar::Int(left), Scalar::Int(right)) => {
                    apply_i64(op, i64::from(*left), i64::from(*right))
                        .map_or(Scalar::Null, |value| Scalar::Int(value as i32))
                }
                _ => Scalar::Null,
            },
            qdb_types::TAG_DOUBLE => match (left, right) {
                (Scalar::Double(left), Scalar::Double(right)) => {
                    apply_f64(op, *left, *right).map_or(Scalar::Null, Scalar::Double)
                }
                _ => Scalar::Null,
            },
            _ => Scalar::Null,
        };
    }
    let left = &table.columns[index][row];
    if left.is_null() || literal.is_null() {
        return Scalar::Null;
    }
    match (result_tag, left, literal) {
        (qdb_types::TAG_LONG, Scalar::Long(left), Scalar::Long(right)) => {
            apply_i64(op, *left, *right).map_or(Scalar::Null, Scalar::Long)
        }
        (qdb_types::TAG_INT, Scalar::Int(left), Scalar::Long(right)) => {
            apply_i64(op, i64::from(*left), *right)
                .map_or(Scalar::Null, |value| Scalar::Int(value as i32))
        }
        (qdb_types::TAG_DOUBLE, Scalar::Double(left), Scalar::Long(right)) => {
            apply_f64(op, *left, *right as f64).map_or(Scalar::Null, Scalar::Double)
        }
        (qdb_types::TAG_DOUBLE, Scalar::Double(left), Scalar::Double(right)) => {
            apply_f64(op, *left, *right).map_or(Scalar::Null, Scalar::Double)
        }
        _ => Scalar::Null,
    }
}

fn resolve_eq(table: &Table, expr: &EqExpr) -> Result<ResolvedProj, Error> {
    let Some(index) = table.column_index(&expr.value) else {
        return Err(Error::new(format!("Invalid column: {}", expr.value)));
    };
    let tag = table.meta.columns[index].tag;
    let other = match &expr.other {
        Some(name) => {
            let other = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            compare_columns(
                &Scalar::Null,
                tag,
                &Scalar::Null,
                table.meta.columns[other].tag,
                expr.op,
            )?;
            Some(other)
        }
        None => None,
    };
    if other.is_none() && !expr.literal.is_null() {
        compare_columns(
            &Scalar::Null,
            tag,
            &Scalar::Null,
            literal_tag(&expr.literal),
            expr.op,
        )?;
    }
    Ok(ResolvedProj::Eq {
        label: expr.label.clone(),
        index,
        op: expr.op,
        literal: expr.literal.clone(),
        other,
    })
}

fn comparison_operator_offset(expr: &EqExpr) -> usize {
    let source = if expr.source_label.is_empty() {
        expr.label.as_str()
    } else {
        expr.source_label.as_str()
    };
    let candidates: &[&str] = match expr.op {
        CmpOp::Eq => &[" = "],
        CmpOp::NotEq => &[" <> ", " != "],
        CmpOp::Lt => &[" < "],
        CmpOp::Gt => &[" > "],
        CmpOp::LtEq => &[" <= "],
        CmpOp::GtEq => &[" >= "],
    };
    candidates
        .iter()
        .find_map(|operator| source.find(operator).map(|offset| offset + 1))
        .unwrap_or(0)
}

fn eq_value(
    table: &Table,
    row: usize,
    index: usize,
    op: CmpOp,
    literal: &Scalar,
    other: Option<usize>,
) -> Result<Scalar, Error> {
    let tag = table.meta.columns[index].tag;
    let left = &table.columns[index][row];
    if let Some(other) = other {
        let right = &table.columns[other][row];
        return compare_columns(left, tag, right, table.meta.columns[other].tag, op)
            .map(Scalar::Boolean);
    }
    let result = if literal.is_null() {
        sql_cmp(left, tag, op, literal)?
    } else {
        compare_columns(left, tag, literal, literal_tag(literal), op)?
    };
    Ok(Scalar::Boolean(result))
}

fn resolve_in_list(table: &Table, expr: &InListExpr) -> Result<ResolvedProj, Error> {
    if expr.args.is_empty() {
        return Err(Error::new("too few arguments for 'in'".to_string()));
    }
    let Some(index) = table.column_index(&expr.value) else {
        return Err(Error::new(format!("Invalid column: {}", expr.value)));
    };
    let tag = table.meta.columns[index].tag;
    let kind = match tag {
        qdb_types::TAG_LONG | qdb_types::TAG_INT | qdb_types::TAG_SHORT | qdb_types::TAG_BYTE => {
            InKind::Integer
        }
        qdb_types::TAG_DOUBLE | qdb_types::TAG_FLOAT => InKind::Float,
        qdb_types::TAG_DATE => InKind::Date,
        qdb_types::TAG_TIMESTAMP => InKind::Timestamp,
        qdb_types::TAG_STRING
        | qdb_types::TAG_SYMBOL
        | qdb_types::TAG_VARCHAR
        | qdb_types::TAG_CHAR => InKind::Text,
        other => return Err(in_type_rejected(qdb_types::type_name(other))),
    };
    let left = qdb_types::type_name(tag);
    let mut items = Vec::with_capacity(expr.args.len());
    for arg in &expr.args {
        items.push(in_item(left, kind, arg)?);
    }
    Ok(ResolvedProj::InList {
        label: expr.label.clone(),
        index,
        items,
        negated: expr.negated,
    })
}

fn in_type_rejected(actual: &str) -> Error {
    Error::new(format!(
        "there is no matching operator `in` with the argument type: {actual}"
    ))
}

fn in_item(left: &str, kind: InKind, arg: &ConcatArg) -> Result<InItem, Error> {
    match (kind, arg) {
        (_, ConcatArg::Literal(Scalar::Null)) => Ok(InItem::Null),
        (InKind::Date, ConcatArg::Literal(Scalar::Text(text))) => {
            if text.chars().count() == 1 {
                return Err(Error::new("cannot compare TIMESTAMP with type CHAR"));
            }
            let date_text = if text.len() == 10 && text.as_bytes().get(4) == Some(&b'-') {
                format!("{text}T00:00:00Z")
            } else {
                text.clone()
            };
            qdb_types::parse_date_millis(&date_text)
                .and_then(|millis| millis.checked_mul(1_000))
                .map(InItem::Long)
                .ok_or_else(|| Error::new(format!("Invalid date: {text}")))
        }
        (InKind::Timestamp, ConcatArg::Literal(Scalar::Text(text))) => {
            qdb_types::parse_timestamp_micros(text)
                .map(InItem::Long)
                .ok_or_else(|| Error::new(format!("Invalid date: {text}")))
        }
        (InKind::Uuid, ConcatArg::Literal(Scalar::Text(text))) if text.chars().count() == 1 => {
            Err(Error::new("cannot compare UUID with type CHAR"))
        }
        (InKind::Uuid, ConcatArg::Literal(Scalar::Text(text))) => canonical_uuid(text)
            .map(InItem::Uuid)
            .ok_or_else(|| Error::new(format!("invalid UUID value [{text}]"))),
        (InKind::Ipv4, ConcatArg::Literal(Scalar::Text(text))) if text.chars().count() == 1 => {
            Err(Error::new("cannot compare IPv4 with type CHAR"))
        }
        (InKind::Ipv4, ConcatArg::Literal(Scalar::Text(text))) => text
            .parse::<std::net::Ipv4Addr>()
            .map(|address| InItem::Ipv4(address.to_string()))
            .map_err(|_| Error::new(format!("invalid IPv4 format: {text}"))),
        (InKind::Date | InKind::Timestamp, ConcatArg::Literal(Scalar::Long(value))) => {
            Ok(InItem::Long(*value))
        }
        (InKind::Integer | InKind::Float, ConcatArg::Literal(Scalar::Long(number))) => {
            Ok(InItem::Long(*number))
        }
        (InKind::Float, ConcatArg::Literal(Scalar::Double(number))) => Ok(InItem::Double(*number)),
        (InKind::Integer, ConcatArg::Literal(Scalar::Text(text))) if text.chars().count() == 1 => {
            Err(Error::new("cannot compare LONG with type CHAR"))
        }
        (InKind::Integer, ConcatArg::Literal(Scalar::Text(text))) => parse_integer_text(text)
            .map(InItem::Long)
            .ok_or_else(|| Error::new(format!("invalid LONG value [{text}]"))),
        (InKind::Float, ConcatArg::Literal(Scalar::Text(text))) if text.chars().count() == 1 => {
            Err(Error::new("cannot compare DOUBLE with type CHAR"))
        }
        (InKind::Float, ConcatArg::Literal(Scalar::Text(text))) => match parse_questdb_f64(text) {
            Some(number) if number.is_finite() => Ok(InItem::Double(number)),
            Some(_) => Ok(InItem::Null),
            None => Err(Error::new(format!("invalid DOUBLE value [{text}]"))),
        },
        (InKind::Text, ConcatArg::Literal(Scalar::Text(text))) => Ok(InItem::Text(text.clone())),
        (InKind::Text, ConcatArg::Literal(Scalar::Char(unit))) => {
            Ok(InItem::Text(in_char_text(*unit)))
        }
        (_, ConcatArg::Column(name)) => {
            Err(Error::new(format!("unsupported: in list column {name}")))
        }
        _ => Err(Error::new(format!(
            "cannot compare {} with type {}",
            match kind {
                InKind::Integer => "LONG",
                InKind::Date | InKind::Timestamp => "TIMESTAMP",
                InKind::Uuid => "UUID",
                InKind::Ipv4 => "IPv4",
                _ => left,
            },
            between_literal_type(arg)
        ))),
    }
}

fn in_char_text(unit: u16) -> String {
    char::from_u32(u32::from(unit))
        .unwrap_or('\u{0}')
        .to_string()
}

fn in_list_value(table: &Table, row: usize, index: usize, items: &[InItem]) -> Scalar {
    Scalar::Boolean(match &table.columns[index][row] {
        Scalar::Null => items.iter().any(|item| matches!(item, InItem::Null)),
        Scalar::Long(number) => in_long(*number, items),
        Scalar::Int(number) => in_long(i64::from(*number), items),
        Scalar::Short(number) => in_long(i64::from(*number), items),
        Scalar::Byte(number) => in_long(i64::from(*number), items),
        Scalar::Double(number) => in_float(*number, items),
        Scalar::Float(number) => in_float(f64::from(*number), items),
        Scalar::Text(text) => in_text(text, items),
        Scalar::Char(unit) => in_text(&in_char_text(*unit), items),
        Scalar::Timestamp(number) => in_long(*number, items),
        Scalar::Date(number) => number
            .checked_mul(1_000)
            .is_some_and(|micros| in_long(micros, items)),
        Scalar::Boolean(_) => false,
    })
}

fn in_long(number: i64, items: &[InItem]) -> bool {
    items
        .iter()
        .any(|item| matches!(item, InItem::Long(value) if *value == number))
}

fn in_float(number: f64, items: &[InItem]) -> bool {
    items.iter().any(|item| match item {
        InItem::Long(value) => number == *value as f64,
        InItem::Double(value) => number == *value,
        _ => false,
    })
}

fn in_text(text: &str, items: &[InItem]) -> bool {
    items.iter().any(|item| match item {
        InItem::Text(value) | InItem::Uuid(value) | InItem::Ipv4(value) => value == text,
        _ => false,
    })
}

fn resolve_wmid(table: &Table, expr: &WmidExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 4 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `wmid`; expected: 4, provided: {}",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::Wmid {
        label: expr.label.clone(),
        bid_size: power_input(table, &expr.args[0])?,
        bid_price: power_input(table, &expr.args[1])?,
        ask_price: power_input(table, &expr.args[2])?,
        ask_size: power_input(table, &expr.args[3])?,
    })
}

fn wmid_number(table: &Table, row: usize, input: &SqrtInput) -> Option<f64> {
    let number = sqrt_number(table, row, input)?;
    if number.is_nan() {
        None
    } else {
        Some(number)
    }
}

fn wmid_value(
    table: &Table,
    row: usize,
    bid_size: &SqrtInput,
    bid_price: &SqrtInput,
    ask_price: &SqrtInput,
    ask_size: &SqrtInput,
) -> Scalar {
    let (Some(bid_size), Some(bid_price), Some(ask_price), Some(ask_size)) = (
        wmid_number(table, row, bid_size),
        wmid_number(table, row, bid_price),
        wmid_number(table, row, ask_price),
        wmid_number(table, row, ask_size),
    ) else {
        return Scalar::Null;
    };
    let imbalance = bid_size / (bid_size + ask_size);
    let value = ask_price * imbalance + bid_price * (1.0 - imbalance);
    Scalar::Double(value)
}

fn resolve_spread_bps(table: &Table, expr: &SpreadBpsExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `spread_bps`; expected: 2, provided: {}",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::SpreadBps {
        label: expr.label.clone(),
        bid: power_input(table, &expr.args[0])?,
        ask: power_input(table, &expr.args[1])?,
    })
}

fn spread_bps_value(table: &Table, row: usize, bid: &SqrtInput, ask: &SqrtInput) -> Scalar {
    let (Some(bid), Some(ask)) = (sqrt_number(table, row, bid), sqrt_number(table, row, ask))
    else {
        return Scalar::Null;
    };
    if bid.is_nan() || ask.is_nan() {
        return Scalar::Null;
    }
    let value = (ask - bid) / ((ask + bid) / 2.0) * 10_000.0;
    Scalar::Double(value)
}

fn power_input(table: &Table, arg: &ConcatArg) -> Result<SqrtInput, Error> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok(SqrtInput::Null),
        ConcatArg::Literal(Scalar::Long(number)) => Ok(SqrtInput::Long(*number)),
        ConcatArg::Literal(Scalar::Double(number)) => Ok(SqrtInput::Double(*number)),
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            let tag = table.meta.columns[index].tag;
            if matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
                    | qdb_types::TAG_FLOAT
                    | qdb_types::TAG_DOUBLE
            ) {
                Ok(SqrtInput::Column { index })
            } else {
                Err(power_type_error(table, arg))
            }
        }
        ConcatArg::Literal(_) => Err(power_type_error(table, arg)),
    }
}

fn power_type_error(table: &Table, arg: &ConcatArg) -> Error {
    match concat_arg_type(table, arg) {
        Ok(actual) => Error::new(format!(
            "expression type mismatch, expected: DOUBLE, actual: {actual}"
        )),
        Err(err) => err,
    }
}

