enum NotInput {
    Const(bool),
    Column(usize),
    Predicate(Box<Filter>),
}

fn resolve_not(table: &Table, expr: &NotExpr) -> Result<ResolvedProj, Error> {
    if let Some(filter) = &expr.filter {
        validate_filter_arithmetic(table, filter).map_err(|error| {
            if let Some(name) = error
                .message
                .strip_prefix("unknown column `")
                .and_then(|message| message.strip_suffix('`'))
            {
                if let Some((_, reference)) = source_dependency_reference(&expr.source_label, name)
                {
                    return Error::new(format!("Invalid column: {reference}"));
                }
            }
            error
        })?;
        if let Filter::Not(inner) = filter.as_ref() {
            if let Filter::BooleanColumn { column } = inner.as_ref() {
                let Some(index) = table.column_index(column) else {
                    return Err(Error::new(format!("Invalid column: {column}")));
                };
                let tag = table.meta.columns[index].tag;
                if tag != qdb_types::TAG_BOOLEAN {
                    return Err(Error::at(
                        format!(
                            "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: {}",
                            qdb_types::type_name(tag)
                        ),
                        0,
                    ));
                }
            } else {
                validate_not_logical_types(table, expr, inner)?;
            }
        } else {
            validate_not_logical_types(table, expr, filter)?;
        }
        return Ok(ResolvedProj::Not {
            label: expr.label.clone(),
            input: NotInput::Predicate(filter.clone()),
        });
    }
    if expr.args.is_empty() {
        return Err(Error::new(
            "too few arguments for 'not' [found=0,expected=1]",
        ));
    }
    let input = not_input(table, expr.args.last().expect("checked"))?;
    Ok(ResolvedProj::Not {
        label: expr.label.clone(),
        input,
    })
}

fn validate_not_logical_types(
    table: &Table,
    expression: &NotExpr,
    filter: &Filter,
) -> Result<(), Error> {
    match filter {
        Filter::And(left, right) | Filter::Or(left, right) => {
            for operand in [left.as_ref(), right.as_ref()] {
                match operand {
                    Filter::BooleanColumn { column } => {
                        let Some(index) = table.column_index(column) else {
                            let dependency = column.rsplit('.').next().unwrap_or(column);
                            if let Some((offset, reference)) =
                                source_dependency_reference(&expression.source_label, dependency)
                            {
                                return Err(Error::at(
                                    format!("Invalid column: {reference}"),
                                    expression.position + offset,
                                ));
                            }
                            return Err(Error::new(format!("Invalid column: {column}")));
                        };
                        let tag = table.meta.columns[index].tag;
                        if tag != qdb_types::TAG_BOOLEAN {
                            let dependency = column.rsplit('.').next().unwrap_or(column);
                            let offset = source_dependency_offset_with_qualifier(
                                &expression.source_label,
                                dependency,
                            )
                            .unwrap_or_default();
                            return Err(Error::at(
                                format!(
                                    "expression type mismatch, expected: BOOLEAN, actual: {}",
                                    qdb_types::type_name(tag)
                                ),
                                expression.position + offset,
                            ));
                        }
                    }
                    Filter::NonBooleanLiteral { value, position } => {
                        let tag = filter_boolean_literal_tag(value);
                        return Err(Error::at(
                            format!(
                                "expression type mismatch, expected: BOOLEAN, actual: {}",
                                qdb_types::type_name(tag)
                            ),
                            expression.position + position,
                        ));
                    }
                    Filter::And(_, _) | Filter::Or(_, _) => {
                        validate_not_logical_types(table, expression, operand)?;
                    }
                    _ => {}
                }
            }
        }
        Filter::Not(inner) => validate_not_logical_types(table, expression, inner)?,
        _ => {}
    }
    Ok(())
}

fn not_projection_error(expression: &NotExpr, error: Error) -> Error {
    let source = expression.source_label.as_ref();
    if is_regex_compilation_error(&error.message) {
        if let Some(position) = error.position {
            return Error::at(error.message, expression.position + position);
        }
    }
    if let Some(name) = error.message.strip_prefix("Invalid column: ") {
        let dependency = name.rsplit('.').next().unwrap_or(name);
        if let Some((offset, reference)) = source_dependency_reference(source, dependency) {
            return Error::at(
                format!("Invalid column: {reference}"),
                expression.position + offset,
            );
        }
    }
    if error
        .message
        .starts_with("argument type mismatch for function `not`")
    {
        if let Some(name) = expression
            .filter
            .as_deref()
            .and_then(not_boolean_column_dependency)
        {
            if let Some(offset) = source_dependency_offset_with_qualifier(source, name) {
                return Error::at(error.message, expression.position + offset);
            }
        }
    }
    if error.message.starts_with("there is no matching operator") {
        let lower = source.to_ascii_lowercase();
        if let Some(offset) = [" ilike ", " like ", " between ", " !~ ", " ~ "]
            .iter()
            .find_map(|operator| lower.find(operator).map(|offset| offset + 1))
        {
            return Error::at(error.message, expression.position + offset);
        }
    }
    if error.message.starts_with("cannot compare") {
        if let Some(offset) = source.find('\'') {
            return Error::at(error.message, expression.position + offset);
        }
    }
    error
}

fn not_boolean_column_dependency(filter: &Filter) -> Option<&str> {
    match filter {
        Filter::Not(inner) => match inner.as_ref() {
            Filter::BooleanColumn { column } => Some(column),
            nested => not_boolean_column_dependency(nested),
        },
        _ => None,
    }
}

fn validate_filter_arithmetic(table: &Table, filter: &Filter) -> Result<(), Error> {
    match filter {
        Filter::CompareExpressions { left, right, .. } => {
            validate_filter_arithmetic_operand(table, left)?;
            validate_filter_arithmetic_operand(table, right)?;
        }
        Filter::InListExpression { value, .. } => {
            validate_filter_arithmetic_operand(table, value)?;
        }
        Filter::Not(inner) => validate_filter_arithmetic(table, inner)?,
        Filter::And(left, right) | Filter::Or(left, right) => {
            validate_filter_arithmetic(table, left)?;
            validate_filter_arithmetic(table, right)?;
        }
        _ => {}
    }
    Ok(())
}

fn in_list_column_index(table: &Table, name: &str) -> Option<usize> {
    table.column_index(name).or_else(|| {
        let (qualifier, column) = name.rsplit_once('.')?;
        qualifier
            .eq_ignore_ascii_case(&table.name)
            .then(|| table.column_index(column))
            .flatten()
    })
}

fn validate_filter_in_expression(table: &Table, filter: &Filter) -> Result<(), Error> {
    match filter {
        Filter::InList {
            column,
            items,
            item_positions,
            position,
            ..
        } => {
            let index = in_list_column_index(table, column)
                .ok_or_else(|| Error::new(format!("Invalid column: {column}")))?;
            if table.meta.columns[index].tag == qdb_types::TAG_BOOLEAN {
                let error = boolean_in_type_error(items);
                return Err(Error::at(error.message, *position));
            }
            let tag = table.meta.columns[index].tag;
            if tag == qdb_types::TAG_SYMBOL || tag == qdb_types::TAG_CHAR {
                let expected = if tag == qdb_types::TAG_SYMBOL {
                    "STRING constant expected"
                } else {
                    "CHAR constant expected"
                };
                for (item_index, item) in items.iter().enumerate() {
                    let valid = match (tag, item) {
                        (_, Scalar::Null) => true,
                        (qdb_types::TAG_SYMBOL, Scalar::Text(_)) => true,
                        (qdb_types::TAG_SYMBOL, Scalar::Char(_)) => true,
                        (qdb_types::TAG_CHAR, Scalar::Text(text)) if text.chars().count() <= 1 => {
                            true
                        }
                        (qdb_types::TAG_CHAR, Scalar::Char(_)) => true,
                        _ => false,
                    };
                    if !valid {
                        return Err(Error::at(
                            expected,
                            item_positions.get(item_index).copied().unwrap_or(*position),
                        ));
                    }
                }
            }
            if tag == qdb_types::TAG_STRING || tag == qdb_types::TAG_VARCHAR {
                let type_name = qdb_types::type_name(tag);
                for (item_index, item) in items.iter().enumerate() {
                    in_item(type_name, InKind::Text, &ConcatArg::Literal(item.clone())).map_err(
                        |error| {
                            Error::at(
                                error.message,
                                item_positions.get(item_index).copied().unwrap_or(*position),
                            )
                        },
                    )?;
                }
            }
            let kind = match tag {
                qdb_types::TAG_LONG
                | qdb_types::TAG_INT
                | qdb_types::TAG_SHORT
                | qdb_types::TAG_BYTE => Some(InKind::Integer),
                qdb_types::TAG_DOUBLE | qdb_types::TAG_FLOAT => Some(InKind::Float),
                qdb_types::TAG_DATE => Some(InKind::Date),
                qdb_types::TAG_TIMESTAMP => Some(InKind::Timestamp),
                _ => None,
            };
            if let Some(kind) = kind {
                let type_name = qdb_types::type_name(tag);
                for (index, item) in items.iter().enumerate() {
                    in_item(type_name, kind, &ConcatArg::Literal(item.clone())).map_err(
                        |error| {
                            Error::at(
                                error.message,
                                item_positions.get(index).copied().unwrap_or(*position),
                            )
                        },
                    )?;
                }
            }
        }
        Filter::InListExpression {
            value,
            items,
            item_positions,
            ..
        } => {
            if let Some(bits) = filter_geohash_bits(table, value)? {
                let error = geohash_in_type_error(bits, items);
                let position = match filter {
                    Filter::InListExpression { position, .. } => *position,
                    _ => unreachable!(),
                };
                return Err(Error::at(error.message, position));
            }
            let tag = select_operand_tag(table, value)?;
            if tag == qdb_types::TAG_BOOLEAN {
                let error = boolean_in_type_error(items);
                let position = match filter {
                    Filter::InListExpression { position, .. } => *position,
                    _ => unreachable!(),
                };
                return Err(Error::at(error.message, position));
            }
            let kind = if filter_is_ipv4(value) {
                InKind::Ipv4
            } else if filter_is_uuid(value) {
                InKind::Uuid
            } else {
                match tag {
                    qdb_types::TAG_LONG
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_BYTE => InKind::Integer,
                    qdb_types::TAG_DOUBLE | qdb_types::TAG_FLOAT => InKind::Float,
                    qdb_types::TAG_DATE => InKind::Date,
                    qdb_types::TAG_TIMESTAMP => InKind::Timestamp,
                    qdb_types::TAG_STRING
                    | qdb_types::TAG_SYMBOL
                    | qdb_types::TAG_VARCHAR
                    | qdb_types::TAG_CHAR => InKind::Text,
                    other => return Err(in_type_rejected(qdb_types::type_name(other))),
                }
            };
            let type_name = match kind {
                InKind::Uuid => "UUID",
                InKind::Ipv4 => "IPv4",
                _ => qdb_types::type_name(tag),
            };
            for (index, item) in items.iter().enumerate() {
                in_item(type_name, kind, &ConcatArg::Literal(item.clone())).map_err(|error| {
                    if error.position.is_none() {
                        Error::at(
                            error.message,
                            item_positions.get(index).copied().unwrap_or_default(),
                        )
                    } else {
                        error
                    }
                })?;
            }
        }
        Filter::Not(inner) => validate_filter_in_expression(table, inner)?,
        Filter::And(left, right) | Filter::Or(left, right) => {
            validate_filter_in_expression(table, left)?;
            validate_filter_in_expression(table, right)?;
        }
        _ => {}
    }
    Ok(())
}

fn filter_geohash_bits(table: &Table, operand: &FilterOperand) -> Result<Option<i32>, Error> {
    let FilterOperand::Projection(projection) = operand else {
        return Ok(None);
    };
    let Proj::MakeGeohash(expression) = projection.as_ref() else {
        return Ok(None);
    };
    let resolved = resolve_make_geohash(table, expression)?;
    let ResolvedProj::MakeGeohash { bits, .. } = resolved else {
        return Err(Error::new("internal: make_geohash"));
    };
    Ok(Some(bits))
}

fn filter_is_uuid(operand: &FilterOperand) -> bool {
    matches!(
        operand,
        FilterOperand::Projection(projection)
            if matches!(projection.as_ref(), Proj::ToUuid(_))
    )
}

fn filter_is_ipv4(operand: &FilterOperand) -> bool {
    matches!(
        operand,
        FilterOperand::Projection(projection)
            if matches!(projection.as_ref(), Proj::Netmask(_))
    )
}

fn geohash_in_type_error(bits: i32, items: &[Scalar]) -> Error {
    let geohash_type = geohash_type_name(bits);
    if items.len() > 1 {
        return Error::new(format!(
            "there is no matching operator `in` with the argument type: {geohash_type}"
        ));
    }
    let item_type = items
        .first()
        .map(|item| {
            if item.is_null() {
                "NULL"
            } else {
                qdb_types::type_name(filter_boolean_literal_tag(item))
            }
        })
        .unwrap_or("NULL");
    Error::new(format!(
        "there is no matching operator `in` with the argument types: {geohash_type} in {item_type}"
    ))
}

fn boolean_in_type_error(items: &[Scalar]) -> Error {
    if items.len() > 1 {
        Error::new("there is no matching operator `in` with the argument type: BOOLEAN")
    } else {
        let item_type = items
            .first()
            .map(|item| {
                if item.is_null() {
                    "NULL"
                } else if matches!(item, Scalar::Text(text) if text.chars().count() == 1) {
                    "CHAR"
                } else {
                    qdb_types::type_name(literal_tag(item))
                }
            })
            .unwrap_or("NULL");
        Error::new(format!(
            "there is no matching operator `in` with the argument types: BOOLEAN in {item_type}"
        ))
    }
}

fn validate_filter_arithmetic_operand(table: &Table, operand: &FilterOperand) -> Result<(), Error> {
    let FilterOperand::Arithmetic(expression) = operand else {
        select_operand_tag(table, operand)?;
        return Ok(());
    };
    validate_filter_arithmetic_operand(table, &expression.left)?;
    validate_filter_arithmetic_operand(table, &expression.right)?;
    let left_tag = select_operand_tag(table, &expression.left)?;
    let right_tag = select_operand_tag(table, &expression.right)?;
    if matches!(
        (left_tag, right_tag),
        (qdb_types::TAG_LONG, qdb_types::TAG_SYMBOL) | (qdb_types::TAG_SYMBOL, qdb_types::TAG_LONG)
    ) {
        let error = arithmetic_type_error(expression.op, left_tag, right_tag, expression.position)
            .expect_err("LONG and SYMBOL arithmetic is unsupported");
        return Err(error);
    }
    select_operand_tag(table, operand)?;
    Ok(())
}

fn not_input(table: &Table, arg: &ConcatArg) -> Result<NotInput, Error> {
    match arg {
        ConcatArg::Column(column) => {
            let Some(index) = table.column_index(column) else {
                return Err(Error::new(format!("Invalid column: {column}")));
            };
            let tag = table.meta.columns[index].tag;
            if tag != qdb_types::TAG_BOOLEAN {
                return Err(Error::new(format!(
                    "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: {}",
                    qdb_types::type_name(tag)
                )));
            }
            Ok(NotInput::Column(index))
        }
        ConcatArg::Literal(Scalar::Null) => Ok(NotInput::Const(true)),
        ConcatArg::Literal(Scalar::Boolean(value)) => Ok(NotInput::Const(!value)),
        _ => Err(Error::new(format!(
            "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: {}",
            atan2_reported_type(table, arg)?
        ))),
    }
}

fn resolve_typeof(table: &Table, expr: &TypeofExpr) -> Result<ResolvedProj, Error> {
    if let Some(arithmetic) = &expr.arithmetic {
        let operand = parse_filter_operand(arithmetic, 0)?;
        let result_tag = select_operand_tag(table, &operand)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: qdb_types::type_name(result_tag).to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if let Some(inner) = &expr.geohash {
        let resolved = resolve_make_geohash(table, inner)?;
        let ResolvedProj::MakeGeohash { bits, .. } = resolved else {
            return Err(Error::new("internal: make_geohash"));
        };
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: geohash_type_name(bits),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if let Some(inner) = &expr.uuid {
        resolve_to_uuid(table, inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "UUID".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if let Some(inner) = &expr.json {
        let resolved = resolve_json_extract(table, inner)?;
        let name = if matches!(resolved, ResolvedProj::JsonExtract { boolean: true, .. }) {
            "BOOLEAN"
        } else {
            "VARCHAR"
        };
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: name.to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    let lowered = expr.label.to_ascii_lowercase();
    if lowered.contains("pg_catalog.age(") || lowered.contains("(age(") {
        let inner = PgAgeExpr {
            label: String::new(),
            source_label: String::new().into(),
            args: expr.args.clone(),
            qualified: lowered.contains("pg_catalog."),
        };
        resolve_pg_age(table, &inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "LONG".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if lowered.contains("pg_table_is_visible(") {
        let inner = PgTableIsVisibleExpr {
            label: String::new(),
            source_label: String::new().into(),
            args: expr.args.clone(),
            qualified: expr.label.to_ascii_lowercase().contains("pg_catalog."),
        };
        resolve_pg_table_is_visible(table, &inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "BOOLEAN".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if lowered.contains("pg_get_expr(") {
        let inner = PgGetExprExpr {
            label: expr.label.clone(),
            source_label: expr.label.clone().into(),
            args: expr.args.clone(),
        };
        resolve_pg_get_expr(table, &inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "STRING".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if lowered.contains("pg_get_partkeydef(") {
        let inner = PgGetPartKeyDefExpr {
            label: expr.label.clone(),
            source_label: expr.label.clone().into(),
            args: expr.args.clone(),
        };
        resolve_pg_get_partkeydef(table, &inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "STRING".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if expr.label.to_ascii_lowercase().contains("pg_get_userbyid(") {
        let inner = PgGetUserByIdExpr {
            label: String::new(),
            source_label: String::new().into(),
            args: expr.args.clone(),
            qualified: expr.label.to_ascii_lowercase().contains("pg_catalog."),
        };
        resolve_pg_get_userbyid(table, &inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "STRING".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if let Some(inner) = &expr.to_char {
        resolve_to_char(table, inner)?;
        return Ok(ResolvedProj::Typeof {
            label: expr.label.clone(),
            name: "STRING".to_string(),
            result_tag: qdb_types::TAG_STRING,
        });
    }
    if expr.args.len() != 1 {
        return Err(Error::new("exactly one argument expected"));
    }
    let (name, result_tag) = typeof_binding(table, &expr.args[0])?;
    Ok(ResolvedProj::Typeof {
        label: expr.label.clone(),
        name: name.to_string(),
        result_tag,
    })
}

fn filter_operand_tag(table: &Table, operand: &FilterOperand) -> Result<i32, Error> {
    match operand {
        FilterOperand::Literal(value) => Ok(literal_tag(value)),
        FilterOperand::Projection(expr) => {
            let resolved = resolve_proj(table, expr)?;
            match &resolved {
                ResolvedProj::Column { index } => Ok(table.meta.columns[*index].tag),
                _ => Ok(resolved.expr_tag()),
            }
        }
        FilterOperand::Arithmetic(expr) => {
            let mut left_tag = filter_operand_tag(table, &expr.left)?;
            let mut right_tag = filter_operand_tag(table, &expr.right)?;
            if left_tag == qdb_types::TAG_SYMBOL
                && matches!(
                    right_tag,
                    qdb_types::TAG_BYTE
                        | qdb_types::TAG_SHORT
                        | qdb_types::TAG_INT
                        | qdb_types::TAG_LONG
                )
            {
                left_tag = qdb_types::TAG_INT;
            } else if right_tag == qdb_types::TAG_SYMBOL
                && matches!(
                    left_tag,
                    qdb_types::TAG_BYTE
                        | qdb_types::TAG_SHORT
                        | qdb_types::TAG_INT
                        | qdb_types::TAG_LONG
                )
            {
                right_tag = qdb_types::TAG_INT;
            }
            if is_text_tag(left_tag)
                && is_numeric_tag(right_tag)
                && !matches!(right_tag, qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP)
            {
                left_tag = right_tag;
            } else if is_text_tag(right_tag)
                && is_numeric_tag(left_tag)
                && !matches!(left_tag, qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP)
            {
                right_tag = left_tag;
            }
            if !is_numeric_tag(left_tag) || !is_numeric_tag(right_tag) {
                let error = arithmetic_type_error(expr.op, left_tag, right_tag, expr.position)
                    .expect_err("arithmetic type validation must fail here");
                return Err(error);
            }
            Ok(arithmetic_result_tag(left_tag, right_tag, expr.op))
        }
    }
}

fn typeof_binding(table: &Table, arg: &ConcatArg) -> Result<(&'static str, i32), Error> {
    let string = qdb_types::TAG_STRING;
    match arg {
        ConcatArg::Column(column) => {
            let Some(index) = table.column_index(column) else {
                return Err(Error::new(format!("Invalid column: {column}")));
            };
            let tag = table.meta.columns[index].tag;
            let result_tag = if tag == qdb_types::TAG_VARCHAR {
                qdb_types::TAG_VARCHAR
            } else {
                string
            };
            Ok((qdb_types::type_name(tag), result_tag))
        }
        ConcatArg::Literal(Scalar::Null) => Ok(("NULL", string)),
        ConcatArg::Literal(Scalar::Boolean(_)) => Ok(("BOOLEAN", string)),
        ConcatArg::Literal(Scalar::Byte(_)) => Ok(("BYTE", string)),
        ConcatArg::Literal(Scalar::Short(_)) => Ok(("SHORT", string)),
        ConcatArg::Literal(Scalar::Char(_)) => Ok(("CHAR", string)),
        ConcatArg::Literal(Scalar::Text(text)) if text.chars().count() == 1 => Ok(("CHAR", string)),
        ConcatArg::Literal(Scalar::Text(_)) => Ok(("STRING", string)),
        ConcatArg::Literal(Scalar::Int(_)) => Ok(("INT", string)),
        ConcatArg::Literal(Scalar::Long(number)) => {
            let name = if *number > i64::from(i32::MIN) && *number <= i64::from(i32::MAX) {
                "INT"
            } else {
                "LONG"
            };
            Ok((name, string))
        }
        ConcatArg::Literal(Scalar::Float(_)) => Ok(("FLOAT", string)),
        ConcatArg::Literal(Scalar::Double(_)) => Ok(("DOUBLE", string)),
        ConcatArg::Literal(Scalar::Date(_)) => Ok(("DATE", string)),
        ConcatArg::Literal(Scalar::Timestamp(_)) => Ok(("TIMESTAMP", string)),
    }
}

fn resolve_atan2(table: &Table, expr: &Atan2Expr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `atan2`; expected: 2, provided: {}",
            expr.args.len()
        )));
    }
    let y_ok = atan2_convertible(table, &expr.args[0])?;
    let x_ok = atan2_convertible(table, &expr.args[1])?;
    if !y_ok || !x_ok {
        let actual = if atan2_reported_type(table, &expr.args[0])? != "DOUBLE" {
            atan2_reported_type(table, &expr.args[0])?
        } else {
            atan2_reported_type(table, &expr.args[1])?
        };
        return Err(Error::new(format!(
            "expression type mismatch, expected: DOUBLE, actual: {actual}"
        )));
    }
    Ok(ResolvedProj::Atan2 {
        label: expr.label.clone(),
        y: resolve_real_arg(table, "atan2", std::slice::from_ref(&expr.args[0]))?,
        x: resolve_real_arg(table, "atan2", std::slice::from_ref(&expr.args[1]))?,
    })
}

fn atan2_convertible(table: &Table, arg: &ConcatArg) -> Result<bool, Error> {
    match arg {
        ConcatArg::Literal(
            Scalar::Null | Scalar::Long(_) | Scalar::Double(_) | Scalar::Text(_) | Scalar::Char(_),
        ) => Ok(true),
        ConcatArg::Column(column) => {
            let Some(index) = table.column_index(column) else {
                return Err(Error::new(format!("Invalid column: {column}")));
            };
            let tag = table.meta.columns[index].tag;
            Ok(matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
                    | qdb_types::TAG_FLOAT
                    | qdb_types::TAG_DOUBLE
                    | qdb_types::TAG_DATE
                    | qdb_types::TAG_TIMESTAMP
                    | qdb_types::TAG_STRING
                    | qdb_types::TAG_VARCHAR
                    | qdb_types::TAG_CHAR
            ))
        }
        _ => Ok(false),
    }
}

fn atan2_reported_type(table: &Table, arg: &ConcatArg) -> Result<&'static str, Error> {
    if let ConcatArg::Literal(Scalar::Long(number)) = arg {
        if *number == i64::from(i32::MIN) {
            return Ok("LONG");
        }
    }
    timestamp_floor_arg_type(table, arg)
}

fn resolve_real_arg(table: &Table, name: &str, args: &[ConcatArg]) -> Result<SinInput, Error> {
    if args.len() != 1 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `{name}`; expected: 1, provided: {}",
            args.len()
        )));
    }
    let input = match &args[0] {
        ConcatArg::Literal(Scalar::Null) => SinInput::Null,
        ConcatArg::Literal(Scalar::Long(number)) => SinInput::Number(*number as f64),
        ConcatArg::Literal(Scalar::Double(number)) => SinInput::Number(*number),
        ConcatArg::Literal(Scalar::Text(text)) => match parse_questdb_f64(text) {
            Some(number) => SinInput::Number(number),
            None => return Err(sin_text_error(text)),
        },
        ConcatArg::Literal(Scalar::Char(unit)) => {
            let ch = char::from_u32(u32::from(*unit)).unwrap_or('\u{0}');
            match parse_questdb_f64(&ch.to_string()) {
                Some(number) => SinInput::Number(number),
                None => {
                    return Err(Error::new(format!(
                        "inconvertible value: {ch} [CHAR -> DOUBLE]"
                    )));
                }
            }
        }
        ConcatArg::Column(column) => {
            let Some(index) = table.column_index(column) else {
                return Err(Error::new(format!("Invalid column: {column}")));
            };
            let tag = table.meta.columns[index].tag;
            if !matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
                    | qdb_types::TAG_FLOAT
                    | qdb_types::TAG_DOUBLE
                    | qdb_types::TAG_DATE
                    | qdb_types::TAG_TIMESTAMP
                    | qdb_types::TAG_STRING
                    | qdb_types::TAG_VARCHAR
                    | qdb_types::TAG_CHAR
            ) {
                return Err(Error::new(format!(
                    "argument type mismatch for function `{name}` at #1 expected: DOUBLE, actual: {}",
                    qdb_types::type_name(tag)
                )));
            }
            SinInput::Column { index, tag }
        }
        _ => {
            return Err(Error::new(format!(
                "argument type mismatch for function `{name}` at #1 expected: DOUBLE, actual: {}",
                timestamp_floor_arg_type(table, &args[0])?
            )));
        }
    };
    Ok(input)
}

fn sin_text_error(text: &str) -> Error {
    if text.chars().count() == 1 {
        let ch = text.chars().next().unwrap_or('\u{0}');
        Error::new(format!("inconvertible value: {ch} [CHAR -> DOUBLE]"))
    } else {
        Error::new(format!("inconvertible value: `{text}` [STRING -> DOUBLE]"))
    }
}

fn resolve_sqrt(table: &Table, expr: &SqrtExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `sqrt`; expected: 1, provided: {}",
            expr.args.len()
        )));
    }
    let input = sqrt_input(table, &expr.args[0])?;
    Ok(ResolvedProj::Sqrt {
        label: expr.label.clone(),
        input,
    })
}

fn sqrt_input(table: &Table, arg: &ConcatArg) -> Result<SqrtInput, Error> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok(SqrtInput::Null),
        ConcatArg::Literal(Scalar::Long(number)) => Ok(SqrtInput::Long(*number)),
        ConcatArg::Literal(Scalar::Double(number)) => Ok(SqrtInput::Double(*number)),
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            let tag = table.meta.columns[index].tag;
            if matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
                    | qdb_types::TAG_FLOAT
                    | qdb_types::TAG_DOUBLE
            ) {
                Ok(SqrtInput::Column { index })
            } else {
                Err(sqrt_type_error(table, arg))
            }
        }
        ConcatArg::Literal(_) => Err(sqrt_type_error(table, arg)),
    }
}

fn sqrt_type_error(table: &Table, arg: &ConcatArg) -> Error {
    match concat_arg_type(table, arg) {
        Ok(actual) => Error::new(format!(
            "argument type mismatch for function `sqrt` at #1 expected: DOUBLE, actual: {actual}"
        )),
        Err(err) => err,
    }
}

fn resolve_sign(table: &Table, expr: &SignExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(named_type_error(table, "sign", &expr.args));
    }
    let (input, result_tag) = sign_input(table, &expr.args[0])
        .map_err(|_| named_type_error(table, "sign", &expr.args))?;
    Ok(ResolvedProj::Sign {
        label: expr.label.clone(),
        input,
        result_tag,
    })
}

fn sign_input(table: &Table, arg: &ConcatArg) -> Result<(SignInput, i32), ()> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok((SignInput::Byte(0), qdb_types::TAG_BYTE)),
        ConcatArg::Literal(Scalar::Long(number)) => {
            if let Ok(number) = i32::try_from(*number) {
                Ok((SignInput::Int(number), qdb_types::TAG_INT))
            } else {
                Ok((SignInput::Long(*number), qdb_types::TAG_LONG))
            }
        }
        ConcatArg::Literal(Scalar::Double(number)) => {
            Ok((SignInput::Double(*number), qdb_types::TAG_DOUBLE))
        }
        ConcatArg::Column(name) => {
            let index = table.column_index(name).ok_or(())?;
            let tag = table.meta.columns[index].tag;
            if matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
                    | qdb_types::TAG_FLOAT
                    | qdb_types::TAG_DOUBLE
            ) {
                Ok((SignInput::Column { index }, tag))
            } else {
                Err(())
            }
        }
        ConcatArg::Literal(_) => Err(()),
    }
}

fn resolve_ceil(table: &Table, expr: &CeilExpr) -> Result<ResolvedProj, Error> {
    let name = function_name(&expr.label);
    if expr.args.len() != 1 {
        if decimal_floor(table, &expr.args) {
            return Err(Error::new(format!("unsupported: decimal {name}")));
        }
        return Err(named_type_error(table, &name, &expr.args));
    }
    let (input, wide) = floor_input(table, &expr.args[0])
        .map_err(|_| named_type_error(table, &name, &expr.args))?;
    Ok(ResolvedProj::Ceil {
        label: expr.label.clone(),
        input,
        wide,
    })
}

fn resolve_floor(table: &Table, expr: &FloorExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        if decimal_floor(table, &expr.args) {
            return Err(Error::new("unsupported: decimal floor"));
        }
        return Err(named_type_error(table, "floor", &expr.args));
    }
    let (input, wide) = floor_input(table, &expr.args[0])
        .map_err(|_| named_type_error(table, "floor", &expr.args))?;
    Ok(ResolvedProj::Floor {
        label: expr.label.clone(),
        input,
        wide,
    })
}

fn decimal_floor(table: &Table, args: &[ConcatArg]) -> bool {
    args.len() == 2 && args.iter().all(|arg| integer_floor_arg(table, arg))
}

fn integer_floor_arg(table: &Table, arg: &ConcatArg) -> bool {
    match arg {
        ConcatArg::Literal(Scalar::Long(_)) => true,
        ConcatArg::Column(name) => table.column_index(name).is_some_and(|index| {
            matches!(
                table.meta.columns[index].tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
            )
        }),
        _ => false,
    }
}

fn floor_input(table: &Table, arg: &ConcatArg) -> Result<(FloorInput, bool), ()> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok((FloorInput::Null, true)),
        ConcatArg::Literal(Scalar::Long(number)) => {
            Ok((FloorInput::Long(*number), i32::try_from(*number).is_err()))
        }
        ConcatArg::Literal(Scalar::Double(number)) => Ok((FloorInput::Double(*number), true)),
        ConcatArg::Column(name) => {
            let index = table.column_index(name).ok_or(())?;
            let tag = table.meta.columns[index].tag;
            let wide = matches!(tag, qdb_types::TAG_LONG | qdb_types::TAG_DOUBLE);
            if wide
                || matches!(
                    tag,
                    qdb_types::TAG_BYTE
                        | qdb_types::TAG_SHORT
                        | qdb_types::TAG_INT
                        | qdb_types::TAG_FLOAT
                )
            {
                Ok((FloorInput::Column { index }, wide))
            } else {
                Err(())
            }
        }
        ConcatArg::Literal(_) => Err(()),
    }
}

enum DateDiffSide {
    Micros(i64),
    Column { index: usize },
    Null,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ToStrOp {
    Lit(String),
    Year(u8),
    IsoYear,
    Month(u8),
    Day(u8),
    DowName(bool),
    DowSun,
    Doy,
    Week(bool),
    AmPm,
    Hour24(bool),
    Hour12(bool),
    HourK(bool),
    HourCapK(bool),
    Minute(bool),
    Second(bool),
    Millis(bool),
    Micros(bool),
    Nanos(bool),
    Era,
    Zone,
}

fn resolve_to_str(table: &Table, expr: &ToStrExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2
        || !matches!(
            &expr.args[1],
            ConcatArg::Literal(Scalar::Null | Scalar::Text(_) | Scalar::Char(_))
        )
    {
        return Err(Error::new(format!(
            "there is no matching function `to_str` with the argument types: ({})",
            timestamp_floor_types(table, &expr.args)?
        )));
    }
    let format = match &expr.args[1] {
        ConcatArg::Literal(Scalar::Null) => return Err(Error::new("format must not be null")),
        ConcatArg::Literal(Scalar::Text(text)) => text.clone(),
        ConcatArg::Literal(Scalar::Char(unit)) => char::from_u32(u32::from(*unit))
            .unwrap_or('\u{0}')
            .to_string(),
        _ => String::new(),
    };
    Ok(ResolvedProj::ToStr {
        label: expr.label.clone(),
        ops: compile_to_str(&format)?,
        value: date_trunc_timestamp(table, &expr.args[0])?,
    })
}

type ToStrToken = (&'static str, fn() -> ToStrOp);

fn compile_to_str(pattern: &str) -> Result<Vec<ToStrOp>, Error> {
    const TOKENS: &[ToStrToken] = &[
        ("yyyy", || ToStrOp::Year(4)),
        ("YYYY", || ToStrOp::IsoYear),
        ("MMMM", || ToStrOp::Month(4)),
        ("yyy", || ToStrOp::Year(3)),
        ("MMM", || ToStrOp::Month(3)),
        ("SSS", || ToStrOp::Millis(true)),
        ("UUU", || ToStrOp::Micros(true)),
        ("NNN", || ToStrOp::Nanos(true)),
        ("zzz", || ToStrOp::Zone),
        ("xxx", || ToStrOp::Zone),
        ("HH", || ToStrOp::Hour24(true)),
        ("hh", || ToStrOp::Hour12(true)),
        ("kk", || ToStrOp::HourK(true)),
        ("KK", || ToStrOp::HourCapK(true)),
        ("mm", || ToStrOp::Minute(true)),
        ("ss", || ToStrOp::Second(true)),
        ("EE", || ToStrOp::DowName(true)),
        ("ww", || ToStrOp::Week(true)),
        ("dd", || ToStrOp::Day(2)),
        ("yy", || ToStrOp::Year(2)),
        ("MM", || ToStrOp::Month(2)),
        ("zz", || ToStrOp::Zone),
        ("xx", || ToStrOp::Zone),
        ("y", || ToStrOp::Year(1)),
        ("M", || ToStrOp::Month(1)),
        ("d", || ToStrOp::Day(1)),
        ("E", || ToStrOp::DowName(false)),
        ("u", || ToStrOp::DowSun),
        ("D", || ToStrOp::Doy),
        ("w", || ToStrOp::Week(false)),
        ("a", || ToStrOp::AmPm),
        ("H", || ToStrOp::Hour24(false)),
        ("h", || ToStrOp::Hour12(false)),
        ("k", || ToStrOp::HourK(false)),
        ("K", || ToStrOp::HourCapK(false)),
        ("m", || ToStrOp::Minute(false)),
        ("s", || ToStrOp::Second(false)),
        ("S", || ToStrOp::Millis(false)),
        ("U", || ToStrOp::Micros(false)),
        ("N", || ToStrOp::Nanos(false)),
        ("G", || ToStrOp::Era),
        ("Z", || ToStrOp::Zone),
        ("z", || ToStrOp::Zone),
        ("x", || ToStrOp::Zone),
    ];
    let mut ops = Vec::new();
    let mut index = 0;
    while index < pattern.len() {
        let rest = &pattern[index..];
        if let Some((token, op)) = TOKENS.iter().find(|(token, _)| rest.starts_with(token)) {
            ops.push(op());
            index += token.len();
        } else {
            let ch = rest.chars().next().unwrap_or('\u{0}');
            ops.push(ToStrOp::Lit(ch.to_string()));
            index += ch.len_utf8();
        }
    }
    Ok(ops)
}

fn format_to_str(ops: &[ToStrOp], micros: i64) -> String {
    let (year, month, day, time) = dateadd_parts(micros);
    let hour = i32::try_from(time / (3_600 * 1_000_000)).unwrap_or(0);
    let minute = i32::try_from((time / (60 * 1_000_000)) % 60).unwrap_or(0);
    let second = i32::try_from((time / 1_000_000) % 60).unwrap_or(0);
    let millis = i32::try_from((time / 1_000) % 1_000).unwrap_or(0);
    let micros_of_milli = i32::try_from(time % 1_000).unwrap_or(0);
    let mut out = String::new();
    for op in ops {
        match op {
            ToStrOp::Lit(text) => out.push_str(text),
            ToStrOp::Year(1) => out.push_str(&year.to_string()),
            ToStrOp::Year(2) => push_padded(&mut out, year.rem_euclid(100), 2),
            ToStrOp::Year(3) => push_padded(&mut out, year.rem_euclid(1000), 3),
            ToStrOp::Year(_) => push_padded(&mut out, year, 4),
            ToStrOp::IsoYear => push_padded(&mut out, iso_year(micros), 4),
            ToStrOp::Month(1) => out.push_str(&month.to_string()),
            ToStrOp::Month(2) => push_padded(&mut out, i32::try_from(month).unwrap_or(0), 2),
            ToStrOp::Month(3) => out.push_str(SHORT_MONTHS[month_index(month)]),
            ToStrOp::Month(_) => out.push_str(LONG_MONTHS[month_index(month)]),
            ToStrOp::Day(1) => out.push_str(&day.to_string()),
            ToStrOp::Day(_) => push_padded(&mut out, i32::try_from(day).unwrap_or(0), 2),
            ToStrOp::DowName(long) => {
                let index = usize::try_from(sunday_weekday(micros) - 1).unwrap_or(0);
                out.push_str(if *long {
                    LONG_DAYS[index.min(6)]
                } else {
                    SHORT_DAYS[index.min(6)]
                });
            }
            ToStrOp::DowSun => out.push_str(&sunday_weekday(micros).to_string()),
            ToStrOp::Doy => out.push_str(&day_of_year(year, micros).to_string()),
            ToStrOp::Week(true) => push_padded(&mut out, week_of_doy(year, micros), 2),
            ToStrOp::Week(false) => out.push_str(&week_of_doy(year, micros).to_string()),
            ToStrOp::AmPm => out.push_str(if hour < 12 { "AM" } else { "PM" }),
            ToStrOp::Hour24(true) => push_padded(&mut out, hour, 2),
            ToStrOp::Hour24(false) => out.push_str(&hour.to_string()),
            ToStrOp::Hour12(padded) => push_hour(&mut out, hour_12(hour), *padded),
            ToStrOp::HourK(padded) => {
                push_hour(&mut out, if hour == 0 { 24 } else { hour }, *padded)
            }
            ToStrOp::HourCapK(padded) => push_hour(&mut out, hour.rem_euclid(12), *padded),
            ToStrOp::Minute(padded) => push_hour(&mut out, minute, *padded),
            ToStrOp::Second(padded) => push_hour(&mut out, second, *padded),
            ToStrOp::Millis(true) => push_padded(&mut out, millis, 3),
            ToStrOp::Millis(false) => out.push_str(&millis.to_string()),
            ToStrOp::Micros(true) => push_padded(&mut out, micros_of_milli, 3),
            ToStrOp::Micros(false) => out.push_str(&micros_of_milli.to_string()),
            ToStrOp::Nanos(true) => out.push_str("000"),
            ToStrOp::Nanos(false) => out.push('0'),
            ToStrOp::Era => out.push_str(if year > 0 { "AD" } else { "BC" }),
            ToStrOp::Zone => out.push('Z'),
        }
    }
    out
}

fn push_hour(out: &mut String, value: i32, padded: bool) {
    if padded {
        push_padded(out, value, 2);
    } else {
        out.push_str(&value.to_string());
    }
}

fn push_padded(out: &mut String, value: i32, width: usize) {
    let text = value.to_string();
    if text.len() >= width {
        out.push_str(&text);
    } else {
        for _ in 0..(width - text.len()) {
            out.push('0');
        }
        out.push_str(&text);
    }
}

fn hour_12(hour: i32) -> i32 {
    match hour.rem_euclid(12) {
        0 => 12,
        other => other,
    }
}

fn month_index(month: u32) -> usize {
    usize::try_from(month.saturating_sub(1))
        .unwrap_or(0)
        .min(11)
}

fn sunday_weekday(micros: i64) -> i32 {
    match weekday_monday(micros) {
        7 => 1,
        day => day + 1,
    }
}

fn day_of_year(year: i32, micros: i64) -> i32 {
    let january = qdb_types::unix_days_from_civil(year, 1, 1).unwrap_or(0);
    i32::try_from(micros.div_euclid(DATEADD_DAY) - january + 1).unwrap_or(0)
}

fn week_of_doy(year: i32, micros: i64) -> i32 {
    day_of_year(year, micros) / 7 + 1
}

fn iso_year(micros: i64) -> i32 {
    let days = micros.div_euclid(DATEADD_DAY);
    let thursday = days + (4 - i64::from(weekday_monday(micros)));
    qdb_types::civil_from_unix_days(thursday).0
}

const SHORT_DAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const LONG_DAYS: [&str; 7] = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
];
const SHORT_MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const LONG_MONTHS: [&str; 12] = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
];

struct TimestampToken {
    op: ToStrOp,
    greedy: bool,
}

fn compile_date_tokens(pattern: &str) -> Vec<TimestampToken> {
    const TOKENS: &[ToStrToken] = &[
        ("yyyy", || ToStrOp::Year(4)),
        ("MMMM", || ToStrOp::Month(4)),
        ("yyy", || ToStrOp::Year(3)),
        ("MMM", || ToStrOp::Month(3)),
        ("SSS", || ToStrOp::Millis(true)),
        ("zzz", || ToStrOp::Zone),
        ("xxx", || ToStrOp::Zone),
        ("HH", || ToStrOp::Hour24(true)),
        ("hh", || ToStrOp::Hour12(true)),
        ("kk", || ToStrOp::HourK(true)),
        ("KK", || ToStrOp::HourCapK(true)),
        ("mm", || ToStrOp::Minute(true)),
        ("ss", || ToStrOp::Second(true)),
        ("dd", || ToStrOp::Day(2)),
        ("yy", || ToStrOp::Year(2)),
        ("MM", || ToStrOp::Month(2)),
        ("zz", || ToStrOp::Zone),
        ("xx", || ToStrOp::Zone),
        ("y", || ToStrOp::Year(1)),
        ("M", || ToStrOp::Month(1)),
        ("d", || ToStrOp::Day(1)),
        ("a", || ToStrOp::AmPm),
        ("H", || ToStrOp::Hour24(false)),
        ("h", || ToStrOp::Hour12(false)),
        ("k", || ToStrOp::HourK(false)),
        ("K", || ToStrOp::HourCapK(false)),
        ("m", || ToStrOp::Minute(false)),
        ("s", || ToStrOp::Second(false)),
        ("S", || ToStrOp::Millis(false)),
        ("Z", || ToStrOp::Zone),
        ("z", || ToStrOp::Zone),
        ("x", || ToStrOp::Zone),
    ];
    let mut ops = Vec::new();
    let mut index = 0;
    while index < pattern.len() {
        let rest = &pattern[index..];
        if let Some((token, op)) = TOKENS.iter().find(|(token, _)| rest.starts_with(token)) {
            ops.push(op());
            index += token.len();
        } else {
            let ch = rest.chars().next().unwrap_or('\u{0}');
            ops.push(ToStrOp::Lit(ch.to_string()));
            index += ch.len_utf8();
        }
    }
    let mut tokens: Vec<TimestampToken> = ops
        .into_iter()
        .map(|op| TimestampToken { op, greedy: false })
        .collect();
    for index in 0..tokens.len() {
        let boundary = matches!(
            tokens[index].op,
            ToStrOp::Lit(_) | ToStrOp::AmPm | ToStrOp::Zone
        );
        if boundary && index > 0 && timestamp_token_is_flexible(&tokens[index - 1].op) {
            tokens[index - 1].greedy = true;
        }
    }
    if let Some(last) = tokens.last_mut() {
        if timestamp_token_is_flexible(&last.op) {
            last.greedy = true;
        }
    }
    tokens
}

fn compile_timestamp_tokens(pattern: &str) -> Vec<TimestampToken> {
    let ops = compile_to_str(pattern).unwrap_or_default();
    let mut tokens: Vec<TimestampToken> = ops
        .into_iter()
        .map(|op| TimestampToken { op, greedy: false })
        .collect();
    for index in 0..tokens.len() {
        let boundary = matches!(
            tokens[index].op,
            ToStrOp::Lit(_) | ToStrOp::AmPm | ToStrOp::Zone
        );
        if boundary && index > 0 && timestamp_token_is_flexible(&tokens[index - 1].op) {
            tokens[index - 1].greedy = true;
        }
    }
    if let Some(last) = tokens.last_mut() {
        if timestamp_token_is_flexible(&last.op) {
            last.greedy = true;
        }
    }
    tokens
}

fn timestamp_token_is_flexible(op: &ToStrOp) -> bool {
    matches!(
        op,
        ToStrOp::Year(1)
            | ToStrOp::Month(1)
            | ToStrOp::Day(1)
            | ToStrOp::Hour24(false)
            | ToStrOp::Hour12(false)
            | ToStrOp::HourK(false)
            | ToStrOp::HourCapK(false)
            | ToStrOp::Minute(false)
            | ToStrOp::Second(false)
            | ToStrOp::Millis(false)
            | ToStrOp::Micros(false)
    )
}

fn parse_timestamp_pattern(tokens: &[TimestampToken], text: &str) -> Option<i64> {
    let chars: Vec<char> = text.chars().collect();
    let mut index = 0;
    let mut year = 1970i32;
    let mut month = 1u32;
    let mut day = 1u32;
    let mut hour = 0i32;
    let mut minute = 0i32;
    let mut second = 0i32;
    let mut millis = 0i32;
    let mut micros = 0i32;
    let mut afternoon = None;
    for token in tokens {
        match &token.op {
            ToStrOp::Lit(literal) => {
                for ch in literal.chars() {
                    if chars.get(index) != Some(&ch) {
                        return None;
                    }
                    index += 1;
                }
            }
            ToStrOp::Year(width) => {
                let (value, len) = read_pattern_digits(&chars, index, *width, token.greedy)?;
                index += len;
                year = if *width == 2 || (token.greedy && len == 2) {
                    adjust_two_digit_year(value)
                } else {
                    value
                };
            }
            ToStrOp::Month(3) => {
                let (value, len) = match_pattern_name(&chars, index, &SHORT_MONTHS)?;
                index += len;
                month = value;
            }
            ToStrOp::Month(4) => {
                let (value, len) = match_pattern_name(&chars, index, &LONG_MONTHS)?;
                index += len;
                month = value;
            }
            ToStrOp::Month(width) => {
                let (value, len) = read_pattern_digits(&chars, index, *width, token.greedy)?;
                index += len;
                month = u32::try_from(value).unwrap_or(0);
            }
            ToStrOp::Day(width) => {
                let (value, len) = read_pattern_digits(&chars, index, *width, token.greedy)?;
                index += len;
                day = u32::try_from(value).unwrap_or(0);
            }
            ToStrOp::Hour24(padded) | ToStrOp::Hour12(padded) => {
                let width = if *padded { 2 } else { 1 };
                let (value, len) = read_pattern_digits(&chars, index, width, token.greedy)?;
                index += len;
                hour = value;
            }
            ToStrOp::Minute(padded) | ToStrOp::Second(padded) => {
                let width = if *padded { 2 } else { 1 };
                let (value, len) = read_pattern_digits(&chars, index, width, token.greedy)?;
                index += len;
                if matches!(token.op, ToStrOp::Minute(_)) {
                    minute = value;
                } else {
                    second = value;
                }
            }
            ToStrOp::Millis(padded) | ToStrOp::Micros(padded) => {
                let width = if *padded { 3 } else { 1 };
                let (value, len) = read_pattern_digits(&chars, index, width, token.greedy)?;
                index += len;
                if matches!(token.op, ToStrOp::Millis(_)) {
                    millis = value;
                } else {
                    micros = value;
                }
            }
            ToStrOp::AmPm => {
                if chars[index..].starts_with(&['A', 'M']) {
                    afternoon = Some(false);
                    index += 2;
                } else if chars[index..].starts_with(&['P', 'M']) {
                    afternoon = Some(true);
                    index += 2;
                } else {
                    return None;
                }
            }
            ToStrOp::Zone if chars.get(index).is_some_and(|ch| *ch == 'Z' || *ch == 'z') => {
                index += 1;
            }
            ToStrOp::Zone => return None,
            _ => return None,
        }
    }
    if index != chars.len() {
        return None;
    }
    if let Some(is_pm) = afternoon {
        if hour == 12 {
            hour = if is_pm { 12 } else { 0 };
        } else if is_pm {
            hour += 12;
        }
    }
    timestamp_from_clock(ParsedClock {
        year,
        month,
        day,
        hour,
        minute,
        second,
        millis,
        micros,
    })
}

fn read_pattern_digits(
    chars: &[char],
    index: usize,
    width: u8,
    greedy: bool,
) -> Option<(i32, usize)> {
    let exact = if greedy { 0 } else { usize::from(width) };
    let limit = if greedy { 9 } else { exact };
    let mut value = 0i32;
    let mut count = 0;
    while count < limit && index + count < chars.len() && chars[index + count].is_ascii_digit() {
        let digit = (u32::from(chars[index + count]) - u32::from('0')) as i32;
        value = value.saturating_mul(10).saturating_add(digit);
        count += 1;
    }
    if greedy {
        (count > 0).then_some((value, count))
    } else if count == exact {
        Some((value, count))
    } else {
        None
    }
}

fn match_pattern_name(chars: &[char], index: usize, names: &[&str]) -> Option<(u32, usize)> {
    for (offset, name) in names.iter().enumerate() {
        let name: Vec<char> = name.chars().collect();
        if chars[index..].starts_with(&name) {
            return Some((u32::try_from(offset + 1).unwrap_or(0), name.len()));
        }
    }
    None
}

fn adjust_two_digit_year(year: i32) -> i32 {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()
        .and_then(|elapsed| i64::try_from(elapsed.as_micros()).ok())
        .unwrap_or(0);
    let reference = dateadd_parts(now).0;
    let offset = reference.rem_euclid(100);
    let low = if offset + 20 > 100 {
        reference - offset + 100
    } else {
        reference - offset
    };
    low + year
}

struct ParsedClock {
    year: i32,
    month: u32,
    day: u32,
    hour: i32,
    minute: i32,
    second: i32,
    millis: i32,
    micros: i32,
}

fn timestamp_from_clock(clock: ParsedClock) -> Option<i64> {
    if !(1..=12).contains(&clock.month)
        || clock.day < 1
        || clock.day > u32::try_from(days_in_month(clock.year, clock.month)).unwrap_or(0)
    {
        return None;
    }
    if !(0..24).contains(&clock.hour)
        || !(0..60).contains(&clock.minute)
        || !(0..60).contains(&clock.second)
    {
        return None;
    }
    if !(0..1_000).contains(&clock.millis) || !(0..1_000).contains(&clock.micros) {
        return None;
    }
    let days = qdb_types::unix_days_from_civil(clock.year, clock.month, clock.day)?;
    Some(
        days * DATEADD_DAY
            + i64::from(clock.hour) * 3_600 * 1_000_000
            + i64::from(clock.minute) * 60 * 1_000_000
            + i64::from(clock.second) * 1_000_000
            + i64::from(clock.millis) * 1_000
            + i64::from(clock.micros),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ExtractPart {
    Year,
    Month,
    Day,
    Hour,
    Minute,
    Second,
    Milliseconds,
    Microseconds,
    Nanoseconds,
    Dow,
    Doy,
    IsoDow,
    IsoYear,
    Week,
    Epoch,
    Century,
    Decade,
    Millennium,
    Quarter,
}

fn extract_part(part: &str) -> Result<ExtractPart, Error> {
    match part.to_ascii_lowercase().as_str() {
        "year" => Ok(ExtractPart::Year),
        "month" => Ok(ExtractPart::Month),
        "day" => Ok(ExtractPart::Day),
        "hour" => Ok(ExtractPart::Hour),
        "minute" => Ok(ExtractPart::Minute),
        "second" => Ok(ExtractPart::Second),
        "milliseconds" => Ok(ExtractPart::Milliseconds),
        "microseconds" => Ok(ExtractPart::Microseconds),
        "nanoseconds" => Ok(ExtractPart::Nanoseconds),
        "dow" => Ok(ExtractPart::Dow),
        "doy" => Ok(ExtractPart::Doy),
        "isodow" => Ok(ExtractPart::IsoDow),
        "isoyear" => Ok(ExtractPart::IsoYear),
        "week" => Ok(ExtractPart::Week),
        "epoch" => Ok(ExtractPart::Epoch),
        "century" => Ok(ExtractPart::Century),
        "decade" => Ok(ExtractPart::Decade),
        "millennium" => Ok(ExtractPart::Millennium),
        "quarter" => Ok(ExtractPart::Quarter),
        _ => Err(Error::new(format!("unsupported timestamp part: {part}"))),
    }
}

fn extract_value(part: ExtractPart, micros: i64) -> Scalar {
    let (year, month, _day, time) = dateadd_parts(micros);
    let hour = i32::try_from(time / (3_600 * 1_000_000)).unwrap_or(0);
    let minute = i32::try_from((time / (60 * 1_000_000)) % 60).unwrap_or(0);
    let second = i32::try_from((time / 1_000_000) % 60).unwrap_or(0);
    match part {
        ExtractPart::Year => Scalar::Int(year),
        ExtractPart::Month => Scalar::Int(i32::try_from(month).unwrap_or(0)),
        ExtractPart::Day => Scalar::Int(i32::try_from(dateadd_parts(micros).2).unwrap_or(0)),
        ExtractPart::Hour => Scalar::Int(hour),
        ExtractPart::Minute => Scalar::Int(minute),
        ExtractPart::Second => Scalar::Int(second),
        ExtractPart::Milliseconds => {
            Scalar::Int(i32::try_from((time / 1_000) % 1_000).unwrap_or(0))
        }
        ExtractPart::Microseconds => Scalar::Int(i32::try_from(time % 1_000_000).unwrap_or(0)),
        ExtractPart::Nanoseconds => {
            Scalar::Int(i32::try_from((time % 1_000_000) * 1_000).unwrap_or(0))
        }
        ExtractPart::Dow => Scalar::Int(sunday_weekday(micros) - 1),
        ExtractPart::Doy => Scalar::Int(day_of_year(year, micros)),
        ExtractPart::IsoDow => Scalar::Int(weekday_monday(micros)),
        ExtractPart::IsoYear => Scalar::Int(iso_year(micros)),
        ExtractPart::Week => Scalar::Int(iso_week(micros)),
        ExtractPart::Epoch => Scalar::Long(micros / 1_000_000),
        ExtractPart::Century => Scalar::Int((year - 1).div_euclid(100) + 1),
        ExtractPart::Decade => Scalar::Int(year.div_euclid(10)),
        ExtractPart::Millennium => Scalar::Int((year - 1).div_euclid(1000) + 1),
        ExtractPart::Quarter => Scalar::Int((i32::try_from(month).unwrap_or(1) - 1) / 3 + 1),
    }
}

fn resolve_extract(table: &Table, expr: &ExtractExpr) -> Result<ResolvedProj, Error> {
    Ok(ResolvedProj::Extract {
        label: expr.label.clone(),
        part: extract_part(&expr.part)?,
        value: date_trunc_timestamp(table, &expr.arg)?,
    })
}

fn md5_hex(message: &[u8]) -> String {
    const SHIFT: [u32; 64] = [
        7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 5, 9, 14, 20, 5, 9, 14, 20, 5,
        9, 14, 20, 5, 9, 14, 20, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 6, 10,
        15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
    ];
    const K: [u32; 64] = [
        0xd76a_a478,
        0xe8c7_b756,
        0x2420_70db,
        0xc1bd_ceee,
        0xf57c_0faf,
        0x4787_c62a,
        0xa830_4613,
        0xfd46_9501,
        0x6980_98d8,
        0x8b44_f7af,
        0xffff_5bb1,
        0x895c_d7be,
        0x6b90_1122,
        0xfd98_7193,
        0xa679_438e,
        0x49b4_0821,
        0xf61e_2562,
        0xc040_b340,
        0x265e_5a51,
        0xe9b6_c7aa,
        0xd62f_105d,
        0x0244_1453,
        0xd8a1_e681,
        0xe7d3_fbc8,
        0x21e1_cde6,
        0xc337_07d6,
        0xf4d5_0d87,
        0x455a_14ed,
        0xa9e3_e905,
        0xfcef_a3f8,
        0x676f_02d9,
        0x8d2a_4c8a,
        0xfffa_3942,
        0x8771_f681,
        0x6d9d_6122,
        0xfde5_380c,
        0xa4be_ea44,
        0x4bde_cfa9,
        0xf6bb_4b60,
        0xbebf_bc70,
        0x289b_7ec6,
        0xeaa1_27fa,
        0xd4ef_3085,
        0x0488_1d05,
        0xd9d4_d039,
        0xe6db_99e5,
        0x1fa2_7cf8,
        0xc4ac_5665,
        0xf429_2244,
        0x432a_ff97,
        0xab94_23a7,
        0xfc93_a039,
        0x655b_59c3,
        0x8f0c_cc92,
        0xffef_f47d,
        0x8584_5dd1,
        0x6fa8_7e4f,
        0xfe2c_e6e0,
        0xa301_4314,
        0x4e08_11a1,
        0xf753_7e82,
        0xbd3a_f235,
        0x2ad7_d2bb,
        0xeb86_d391,
    ];
    let mut state = [0x6745_2301_u32, 0xefcd_ab89, 0x98ba_dcfe, 0x1032_5476];
    let bit_len = (message.len() as u64).wrapping_mul(8);
    let mut data = message.to_vec();
    data.push(0x80);
    while data.len() % 64 != 56 {
        data.push(0);
    }
    data.extend_from_slice(&bit_len.to_le_bytes());
    for chunk in data.chunks_exact(64) {
        let mut words = [0_u32; 16];
        for (index, word) in words.iter_mut().enumerate() {
            let start = index * 4;
            let mut buf = [0_u8; 4];
            buf.copy_from_slice(&chunk[start..start + 4]);
            *word = u32::from_le_bytes(buf);
        }
        let (mut a, mut b, mut c, mut d) = (state[0], state[1], state[2], state[3]);
        for index in 0..64 {
            let (mixed, source) = match index {
                0..=15 => ((b & c) | (!b & d), index),
                16..=31 => ((b & d) | (c & !d), (5 * index + 1) % 16),
                32..=47 => (b ^ c ^ d, (3 * index + 5) % 16),
                _ => (c ^ (b | !d), (7 * index) % 16),
            };
            let mixed = mixed
                .wrapping_add(a)
                .wrapping_add(K[index])
                .wrapping_add(words[source]);
            a = d;
            d = c;
            c = b;
            b = b.wrapping_add(mixed.rotate_left(SHIFT[index]));
        }
        state[0] = state[0].wrapping_add(a);
        state[1] = state[1].wrapping_add(b);
        state[2] = state[2].wrapping_add(c);
        state[3] = state[3].wrapping_add(d);
    }
    let mut out = String::with_capacity(32);
    for word in state {
        for byte in word.to_le_bytes() {
            out.push(char::from(b"0123456789abcdef"[(byte >> 4) as usize]));
            out.push(char::from(b"0123456789abcdef"[(byte & 0x0f) as usize]));
        }
    }
    out
}

fn sha256_hex(message: &[u8]) -> String {
    const K: [u32; 64] = [
        0x428a_2f98,
        0x7137_4491,
        0xb5c0_fbcf,
        0xe9b5_dba5,
        0x3956_c25b,
        0x59f1_11f1,
        0x923f_82a4,
        0xab1c_5ed5,
        0xd807_aa98,
        0x1283_5b01,
        0x2431_85be,
        0x550c_7dc3,
        0x72be_5d74,
        0x80de_b1fe,
        0x9bdc_06a7,
        0xc19b_f174,
        0xe49b_69c1,
        0xefbe_4786,
        0x0fc1_9dc6,
        0x240c_a1cc,
        0x2de9_2c6f,
        0x4a74_84aa,
        0x5cb0_a9dc,
        0x76f9_88da,
        0x983e_5152,
        0xa831_c66d,
        0xb003_27c8,
        0xbf59_7fc7,
        0xc6e0_0bf3,
        0xd5a7_9147,
        0x06ca_6351,
        0x1429_2967,
        0x27b7_0a85,
        0x2e1b_2138,
        0x4d2c_6dfc,
        0x5338_0d13,
        0x650a_7354,
        0x766a_0abb,
        0x81c2_c92e,
        0x9272_2c85,
        0xa2bf_e8a1,
        0xa81a_664b,
        0xc24b_8b70,
        0xc76c_51a3,
        0xd192_e819,
        0xd699_0624,
        0xf40e_3585,
        0x106a_a070,
        0x19a4_c116,
        0x1e37_6c08,
        0x2748_774c,
        0x34b0_bcb5,
        0x391c_0cb3,
        0x4ed8_aa4a,
        0x5b9c_ca4f,
        0x682e_6ff3,
        0x748f_82ee,
        0x78a5_636f,
        0x84c8_7814,
        0x8cc7_0208,
        0x90be_fffa,
        0xa450_6ceb,
        0xbef9_a3f7,
        0xc671_78f2,
    ];
    let mut state = [
        0x6a09_e667_u32,
        0xbb67_ae85,
        0x3c6e_f372,
        0xa54f_f53a,
        0x510e_527f,
        0x9b05_688c,
        0x1f83_d9ab,
        0x5be0_cd19,
    ];
    let bit_len = (message.len() as u64).wrapping_mul(8);
    let mut data = message.to_vec();
    data.push(0x80);
    while data.len() % 64 != 56 {
        data.push(0);
    }
    data.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in data.chunks_exact(64) {
        let mut words = [0_u32; 64];
        for (word, bytes) in words.iter_mut().zip(chunk.chunks_exact(4)) {
            let mut buf = [0_u8; 4];
            buf.copy_from_slice(bytes);
            *word = u32::from_be_bytes(buf);
        }
        for index in 16..64 {
            let older = words[index - 15];
            let recent = words[index - 2];
            let small = older.rotate_right(7) ^ older.rotate_right(18) ^ (older >> 3);
            let large = recent.rotate_right(17) ^ recent.rotate_right(19) ^ (recent >> 10);
            words[index] = words[index - 16]
                .wrapping_add(small)
                .wrapping_add(words[index - 7])
                .wrapping_add(large);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut h) = (
            state[0], state[1], state[2], state[3], state[4], state[5], state[6], state[7],
        );
        for (index, word) in words.iter().enumerate() {
            let upper = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let choice = (e & f) ^ (!e & g);
            let first = h
                .wrapping_add(upper)
                .wrapping_add(choice)
                .wrapping_add(K[index])
                .wrapping_add(*word);
            let lower = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let majority = (a & b) ^ (a & c) ^ (b & c);
            let second = lower.wrapping_add(majority);
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(first);
            d = c;
            c = b;
            b = a;
            a = first.wrapping_add(second);
        }
        state[0] = state[0].wrapping_add(a);
        state[1] = state[1].wrapping_add(b);
        state[2] = state[2].wrapping_add(c);
        state[3] = state[3].wrapping_add(d);
        state[4] = state[4].wrapping_add(e);
        state[5] = state[5].wrapping_add(f);
        state[6] = state[6].wrapping_add(g);
        state[7] = state[7].wrapping_add(h);
    }
    let mut out = String::with_capacity(64);
    for word in state {
        for byte in word.to_be_bytes() {
            out.push(char::from(b"0123456789abcdef"[(byte >> 4) as usize]));
            out.push(char::from(b"0123456789abcdef"[(byte & 0x0f) as usize]));
        }
    }
    out
}

fn sha1_hex(message: &[u8]) -> String {
    let mut state = [
        0x6745_2301_u32,
        0xefcd_ab89,
        0x98ba_dcfe,
        0x1032_5476,
        0xc3d2_e1f0,
    ];
    let bit_len = (message.len() as u64).wrapping_mul(8);
    let mut data = message.to_vec();
    data.push(0x80);
    while data.len() % 64 != 56 {
        data.push(0);
    }
    data.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in data.chunks_exact(64) {
        let mut words = [0_u32; 80];
        for (word, bytes) in words.iter_mut().zip(chunk.chunks_exact(4)) {
            let mut buf = [0_u8; 4];
            buf.copy_from_slice(bytes);
            *word = u32::from_be_bytes(buf);
        }
        for index in 16..80 {
            words[index] =
                (words[index - 3] ^ words[index - 8] ^ words[index - 14] ^ words[index - 16])
                    .rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) =
            (state[0], state[1], state[2], state[3], state[4]);
        for (index, word) in words.iter().enumerate() {
            let (mixed, constant) = match index {
                0..=19 => ((b & c) | (!b & d), 0x5a82_7999),
                20..=39 => (b ^ c ^ d, 0x6ed9_eba1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8f1b_bcdc),
                _ => (b ^ c ^ d, 0xca62_c1d6),
            };
            let mixed = a
                .rotate_left(5)
                .wrapping_add(mixed)
                .wrapping_add(e)
                .wrapping_add(constant)
                .wrapping_add(*word);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = mixed;
        }
        state[0] = state[0].wrapping_add(a);
        state[1] = state[1].wrapping_add(b);
        state[2] = state[2].wrapping_add(c);
        state[3] = state[3].wrapping_add(d);
        state[4] = state[4].wrapping_add(e);
    }
    let mut out = String::with_capacity(40);
    for word in state {
        for byte in word.to_be_bytes() {
            out.push(char::from(b"0123456789abcdef"[(byte >> 4) as usize]));
            out.push(char::from(b"0123456789abcdef"[(byte & 0x0f) as usize]));
        }
    }
    out
}

fn resolve_sha256(table: &Table, expr: &Sha256Expr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(Error::new(format!(
            "there is no matching function `sha256` with the argument types: ({})",
            timestamp_floor_types(table, &expr.args)?
        )));
    }
    let arg = match &expr.args[0] {
        ConcatArg::Literal(Scalar::Null) => ResolvedArg::Null,
        ConcatArg::Literal(Scalar::Text(text)) => ResolvedArg::Text(text.clone()),
        ConcatArg::Literal(Scalar::Char(0)) => ResolvedArg::Null,
        ConcatArg::Literal(Scalar::Char(unit)) => ResolvedArg::Text(
            char::from_u32(u32::from(*unit))
                .unwrap_or('\u{0}')
                .to_string(),
        ),
        ConcatArg::Column(name) => {
            let Some(index) = table.column_index(name) else {
                return Err(Error::new(format!("Invalid column: {name}")));
            };
            let tag = table.meta.columns[index].tag;
            if !matches!(
                tag,
                qdb_types::TAG_STRING
                    | qdb_types::TAG_SYMBOL
                    | qdb_types::TAG_VARCHAR
                    | qdb_types::TAG_CHAR
            ) {
                return Err(Error::new(format!(
                    "there is no matching function `sha256` with the argument types: ({})",
                    timestamp_floor_types(table, &expr.args)?
                )));
            }
            ResolvedArg::Column { index, tag }
        }
        _ => {
            return Err(Error::new(format!(
                "there is no matching function `sha256` with the argument types: ({})",
                timestamp_floor_types(table, &expr.args)?
            )));
        }
    };
    Ok(ResolvedProj::Sha256 {
        label: expr.label.clone(),
        arg,
    })
}

