fn days_in_month(year: i32, month: u32) -> i32 {
    const DAYS: [i32; 12] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if month == 2 && is_leap_year(year) {
        29
    } else {
        DAYS[(month.saturating_sub(1) as usize).min(11)]
    }
}

