    #[test]
    fn symbol_cursor_projection_headers_match_questdb_without_aliases() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        for (sql, expected) in [
            (
                "SELECT location IN (SELECT location FROM sensors WHERE location='madrid') FROM sensors ORDER BY ts",
                "location in (select-choose location from (sensors where location\ntrue\nfalse\ntrue\nfalse\n",
            ),
            (
                "SELECT location NOT IN (SELECT tag FROM sensors) FROM sensors ORDER BY ts",
                "not(location in (select-choose tag from (sensors)))\ntrue\nfalse\ntrue\ntrue\n",
            ),
            (
                "SELECT location IN (SELECT location FROM sensors WHERE id=99) FROM sensors ORDER BY ts",
                "location in (select-choose location from (sensors where id = 99)\nfalse\nfalse\nfalse\nfalse\n",
            ),
            (
                "SELECT location IN (SELECT location FROM sensors) FROM sensors",
                "location in (select-choose location from (sensors))\ntrue\ntrue\ntrue\ntrue\n",
            ),
            (
                "SELECT location IN (SELECT lower(location) FROM sensors WHERE location='madrid') FROM sensors ORDER BY ts",
                "location in (select-choose lower(location) lower(location) from\ntrue\nfalse\ntrue\nfalse\n",
            ),
            (
                "SELECT ts, location IN (SELECT location FROM sensors WHERE location='madrid') FROM sensors ORDER BY ts",
                "ts\tlocation in (select-choose location from (sensors where location\n2020-01-02T03:04:05.000000Z\ttrue\n2020-01-02T03:04:06.000000Z\tfalse\n2020-01-02T03:04:07.000000Z\ttrue\n2020-01-02T03:04:08.000000Z\tfalse\n",
            ),
        ] {
            let actual = execute(&sensors, sql).unwrap_or_else(|error| panic!("{sql}: {error:?}"));
            assert_eq!(render_tsv(&actual), expected, "{sql}");
        }
        for (sql, name) in [
            (
                "SELECT location IN (SELECT min(location) FROM sensors) FROM sensors ORDER BY ts",
                "projection_no_alias_aggregate",
            ),
            (
                "SELECT location IN (SELECT location FROM sensors GROUP BY location) FROM sensors ORDER BY ts",
                "projection_no_alias_group",
            ),
            (
                "SELECT location IN (SELECT t.location FROM sensors s JOIN sensors t ON s.id=t.id) FROM sensors ORDER BY ts",
                "projection_no_alias_join",
            ),
            (
                "SELECT location IN (SELECT location FROM sensors WHERE location IN (SELECT location FROM sensors WHERE location='madrid')) FROM sensors ORDER BY ts",
                "projection_no_alias_nested",
            ),
            (
                "SELECT location IN (SELECT location FROM sensors ORDER BY ts LIMIT 1) FROM sensors ORDER BY ts",
                "projection_no_alias_order_limit",
            ),
            (
                "SELECT location IN (SELECT min(location) FROM sensors GROUP BY location) FROM sensors ORDER BY ts",
                "projection_no_alias_grouped_aggregate",
            ),
        ] {
            let expected = std::fs::read_to_string(
                sensors.join(format!("expected/symbol_subquery_{name}.tsv")),
            )
            .unwrap();
            let actual = execute(&sensors, sql).unwrap_or_else(|error| panic!("{sql}: {error:?}"));
            assert_eq!(render_tsv(&actual), expected, "{sql}");
        }
    }

    #[test]
    fn replace_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                sensors.clone(),
                "SELECT replace(note, 'a', 'X') FROM sensors",
                "expected/rep_note.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(s.note, 'a', 'A') FROM sensors AS s",
                "expected/rep_qualified_note.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(note, 'ta', '') FROM sensors",
                "expected/rep_drop.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('βeta', 'β', 'B') FROM sensors LIMIT 1",
                "expected/rep_beta.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(null, 'a', 'b') FROM sensors LIMIT 1",
                "expected/rep_null.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('ab', null, 'c') FROM sensors LIMIT 1",
                "expected/rep_null_old.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('ab', 'a', null) FROM sensors LIMIT 1",
                "expected/rep_null_new.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('', 'a', 'b') FROM sensors LIMIT 1",
                "expected/rep_empty.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('aaa', 'a', 'bb') FROM sensors LIMIT 1",
                "expected/rep_grow.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('aaa', 'aa', 'b') FROM sensors LIMIT 1",
                "expected/rep_overlap.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('abc', '', 'x') FROM sensors LIMIT 1",
                "expected/rep_empty_old.tsv",
            ),
            (
                sensors.clone(),
                "SELECT REPLACE(NOTE, 'a', 'A') FROM sensors",
                "expected/rep_case.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(note, 'a', 'X') FROM sensors ORDER BY replace(note, 'a', 'X')",
                "expected/rep_order.tsv",
            ),
            (
                sensors.clone(),
                "SELECT id, replace(note, 'a', 'X') FROM sensors ORDER BY replace(note, 'a', 'X')",
                "expected/rep_with_id.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(note, 'a', 'X') FROM sensors WHERE note = ''",
                "expected/rep_where_empty.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(note, 'a', 'X') FROM sensors LIMIT 0",
                "expected/rep_limit_zero.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(note, 'a', location) FROM sensors",
                "expected/rep_symbol.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('ab', location, 'x') FROM sensors",
                "expected/rep_const_symbol.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace('', location, 'x') FROM sensors",
                "expected/rep_empty_value.tsv",
            ),
            (
                sensors.clone(),
                "SELECT replace(tag, '0', 'x') FROM sensors",
                "expected/rep_tag.tsv",
            ),
            (
                days.clone(),
                "SELECT replace(note, 'a', 'X') FROM days",
                "expected/rep_note.tsv",
            ),
            (
                days.clone(),
                "SELECT replace(location, 'a', 'A') FROM days ORDER BY ts",
                "expected/rep_location.tsv",
            ),
        ];
        for (root, sql, file) in cases {
            let result = execute(&root, sql).unwrap();
            let expected = std::fs::read_to_string(root.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT replace() FROM sensors").unwrap_err();
        assert!(
            err.message.contains("requires arguments"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT replace(note) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `replace` with the argument types: (STRING)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT replace(note, 'a') FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `replace` with the argument types: (STRING, CHAR)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT replace(note, 'ab') FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `replace` with the argument types: (STRING, STRING)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT replace(id, '1', '2') FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `replace` with the argument types: (LONG, CHAR, CHAR)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT replace(missing, 'a', 'b') FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
    }

    #[test]
    fn cc_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                &sensors,
                "SELECT id + id FROM sensors",
                "expected/cc_all.tsv",
            ),
            (
                &sensors,
                "SELECT id + id FROM sensors WHERE id = 1",
                "expected/cc_one.tsv",
            ),
            (
                &sensors,
                "SELECT id + id FROM sensors WHERE id = 2",
                "expected/cc_two.tsv",
            ),
            (
                &sensors,
                "SELECT id + id FROM sensors WHERE id > 100",
                "expected/cc_none.tsv",
            ),
            (
                &sensors,
                "SELECT reading + reading FROM sensors",
                "expected/cc_read.tsv",
            ),
            (
                &sensors,
                "SELECT flags + flags FROM sensors",
                "expected/cc_flags.tsv",
            ),
            (
                &sensors,
                "SELECT id + flags FROM sensors",
                "expected/cc_mix.tsv",
            ),
            (&days, "SELECT id + id FROM days", "expected/cc_days.tsv"),
        ];
        for (dir, sql, file) in cases {
            let result = execute(dir, sql).unwrap();
            let expected = std::fs::read_to_string(dir.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT id + missing FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
    }

