    #[test]
    fn pg_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                &sensors,
                "SELECT to_pg_date(s.note) FROM sensors AS s",
                "expected/pg_qualified_note.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('2020-01-02') FROM sensors LIMIT 1",
                "expected/pg_lit.tsv",
            ),
            (
                &sensors,
                "SELECT TO_PG_DATE('2020-01-02') FROM sensors LIMIT 1",
                "expected/pg_case.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('1970-01-01') FROM sensors LIMIT 1",
                "expected/pg_epoch.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('1969-12-31') FROM sensors LIMIT 1",
                "expected/pg_prev.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('2020-06-15') FROM sensors LIMIT 1",
                "expected/pg_june.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('2020-01-02 03:04:05') FROM sensors LIMIT 1",
                "expected/pg_time.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('2020-01-02T03:04:05.000000Z') FROM sensors LIMIT 1",
                "expected/pg_iso.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('') FROM sensors LIMIT 1",
                "expected/pg_empty.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date('nope') FROM sensors LIMIT 1",
                "expected/pg_nope.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(null) FROM sensors LIMIT 1",
                "expected/pg_null.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(note) FROM sensors",
                "expected/pg_note.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(ch) FROM sensors",
                "expected/pg_ch.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(location) FROM sensors",
                "expected/pg_loc.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(tag) FROM sensors",
                "expected/pg_tag.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(note) FROM sensors WHERE id = 1",
                "expected/pg_one.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(note) FROM sensors WHERE id > 100",
                "expected/pg_none.tsv",
            ),
            (
                &sensors,
                "SELECT to_pg_date(note) FROM sensors LIMIT 0",
                "expected/pg_lim0.tsv",
            ),
            (
                &days,
                "SELECT to_pg_date(note) FROM days",
                "expected/pg_days.tsv",
            ),
        ];
        for (dir, sql, file) in cases {
            let result = execute(dir, sql).unwrap();
            let expected = std::fs::read_to_string(dir.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT to_pg_date() FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("function `to_pg_date` requires arguments"),
            "{}",
            err.message
        );
        let rejected = [
            (
                "SELECT to_pg_date(ts) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (TIMESTAMP)",
            ),
            (
                "SELECT to_pg_date(day) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (DATE)",
            ),
            (
                "SELECT to_pg_date(id) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (LONG)",
            ),
            (
                "SELECT to_pg_date(flags) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (INT)",
            ),
            (
                "SELECT to_pg_date(ok) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (BOOLEAN)",
            ),
            (
                "SELECT to_pg_date(reading) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (DOUBLE)",
            ),
            (
                "SELECT to_pg_date(b) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (BYTE)",
            ),
            (
                "SELECT to_pg_date(ts, 1) FROM sensors",
                "there is no matching function `to_pg_date` with the argument types: (TIMESTAMP, INT)",
            ),
        ];
        for (sql, message) in rejected {
            let err = execute(&sensors, sql).unwrap_err();
            assert!(err.message.contains(message), "{}", err.message);
        }
        let err = execute(&sensors, "SELECT to_pg_date(missing) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
    }

    #[test]
    fn tz_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                &sensors,
                "SELECT to_timezone(s.ts, 'Europe/Madrid') FROM sensors AS s",
                "expected/tz_qualified_ts.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(ts, 'UTC') FROM sensors",
                "expected/tz_utc.tsv",
            ),
            (
                &sensors,
                "SELECT TO_TIMEZONE(ts, 'UTC') FROM sensors",
                "expected/tz_case.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(ts, 'Europe/Madrid') FROM sensors",
                "expected/tz_mad.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(ts, 'Europe/Madrid') FROM sensors WHERE id = 1",
                "expected/tz_one.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(ts, 'America/New_York') FROM sensors",
                "expected/tz_ny.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(day, 'UTC') FROM sensors",
                "expected/tz_day.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(day, 'Europe/Madrid') FROM sensors",
                "expected/tz_dmad.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(day, 'America/New_York') FROM sensors",
                "expected/tz_dny.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(id, 'UTC') FROM sensors",
                "expected/tz_id.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(flags, 'UTC') FROM sensors",
                "expected/tz_flags.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(ts, 'UTC') FROM sensors WHERE id > 100",
                "expected/tz_none.tsv",
            ),
            (
                &sensors,
                "SELECT to_timezone(ts, 'UTC') FROM sensors LIMIT 0",
                "expected/tz_lim0.tsv",
            ),
            (
                &days,
                "SELECT to_timezone(ts, 'UTC') FROM days",
                "expected/tz_days.tsv",
            ),
        ];
        for (dir, sql, file) in cases {
            let result = execute(dir, sql).unwrap();
            let expected = std::fs::read_to_string(dir.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT to_timezone() FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "function `to_timezone` requires arguments: to_timezone(TIMESTAMP, STRING)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(ts) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "wrong number of arguments for function `to_timezone`; expected: 2, provided: 1"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(ts, 'UTC', 1) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "wrong number of arguments for function `to_timezone`; expected: 2, provided: 3"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(ts, 'Mars') FROM sensors").unwrap_err();
        assert!(
            err.message.contains("invalid timezone: Mars"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(ts, null) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("timezone must not be null"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(ok, 'UTC') FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("expression type mismatch, expected: TIMESTAMP, actual: BOOLEAN"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(ch, 'UTC') FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("expression type mismatch, expected: TIMESTAMP, actual: CHAR"),
            "{}",
            err.message
        );
        let err =
            execute(&sensors, "SELECT to_timezone(location, 'UTC') FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `madrid` [SYMBOL -> TIMESTAMP_NS]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(note, 'UTC') FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `alpha` [STRING -> TIMESTAMP_NS]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT to_timezone(missing, 'UTC') FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
    }

